import type { ReactNode } from 'react';
import { useEmbedChatHeader } from './header.hooks.js';

export interface EmbedHeaderCopy {
  readonly eyebrow: string;
  readonly newThread: string;
  readonly cancel: string;
  readonly discard: string;
}
export interface EscapeKeyPort { subscribe(args: { onEscape: () => void }): () => void }
export interface EmbedChatHeaderArgs {
  readonly title: string;
  readonly hasMessages: boolean;
  readonly onReset: () => void;
  readonly copy: EmbedHeaderCopy;
  readonly keyboard: EscapeKeyPort;
  readonly closeAction?: ReactNode;
}
/** Two-step reset with safe initial focus, Cancel and host-wide Escape. O(1) state and listeners. */
export function EmbedChatHeader({ title, hasMessages, onReset, copy, keyboard, closeAction }: EmbedChatHeaderArgs) {
  const { confirming, cancel, requestReset, confirmReset, headerRef, resetButtonRef } = useEmbedChatHeader({ hasMessages, onReset, keyboard });
  return <div className="jini-chat-pane__header" ref={headerRef}>
    <div className="jini-chat-pane__heading">
      {copy.eyebrow && <span className="jini-chat-pane__eyebrow">{copy.eyebrow}</span>}
      <h2 className="jini-chat-pane__title">{title}</h2>
    </div>
    {confirming ? <div className="jini-chat-embed__reset-confirm">
      <button type="button" className="jini-chat-embed__reset-cancel" autoFocus onClick={cancel}>{copy.cancel}</button>
      <button type="button" className="jini-chat-pane__new-thread" onClick={confirmReset}>{copy.discard}</button>
    </div> : <button type="button" className="jini-chat-pane__new-thread" ref={resetButtonRef} onClick={requestReset}>{copy.newThread}</button>}
    {closeAction}
  </div>;
}

/**
 * @module AttachmentPreviewModal
 *
 * The "can we see it again" modal `MessageRow.tsx`'s attachment chip opens: an image scaled to fit,
 * a scrollable monospace pane for a text-ish file, or - honestly, never a faked preview - the
 * filename/type/size for anything else. All state/effects live in `useAttachmentPreviewModal`; this
 * is the presentational shell, native-`<dialog>`-based like `Markdown.tsx`'s `TableBlock` pop-out.
 * With `navigation` (more than one image in the message or the composer's staged set) a footer adds
 * previous/next side by side in the bottom-right corner, plus ←/→ on the dialog.
 */
import { useT } from '../hooks/context.js';
import { Icon } from './Icon.js';
import type { ChatAttachment } from '../../core/index.js';
import { looksLikeImageAttachment, useAttachmentPreviewModal, type AttachmentPreviewController } from './AttachmentPreviewModal.hooks.js';
import type { AttachmentPreviewNavigation } from './AttachmentGallery.hooks.js';

export interface AttachmentPreviewModalProps {
  attachment: ChatAttachment;
  onClose: () => void;
  /** Previous/next over the surrounding images; omitted for a lone attachment. */
  navigation?: AttachmentPreviewNavigation | undefined;
}

export function AttachmentPreviewModal({ attachment, onClose, navigation }: AttachmentPreviewModalProps) {
  const t = useT();
  const c = useAttachmentPreviewModal({ attachment: attachment, onClose: onClose, navigation });

  return (
    <dialog
      ref={c.dialogRef}
      className={`jini-attachment-preview-dialog${navigation ? ' has-nav' : ''}`}
      role="dialog"
      aria-modal="true"
      aria-label={t('{name} preview', { name: attachment.name })}
      onCancel={c.handleNativeCancel}
      onClick={c.handleBackdropClick}
      onKeyDown={c.handleKeyDown}
    >
      <div className="jini-attachment-preview-header">
        <span className="jini-attachment-preview-name" title={attachment.name}>
          {attachment.name}
        </span>
        <button
          type="button"
          className="jini-attachment-preview-close"
          onClick={onClose}
          title={t('Close')}
          aria-label={t('Close')}
        >
          <Icon name="close" size={16} />
        </button>
      </div>
      <div className="jini-attachment-preview-body">
        <AttachmentPreviewBody attachment={attachment} preview={c} />
      </div>
      {navigation ? <AttachmentPreviewNav navigation={navigation} /> : null}
    </dialog>
  );
}

interface AttachmentPreviewBodyProps {
  attachment: ChatAttachment;
  preview: AttachmentPreviewController;
}

/** The image, the text pane, or - for anything else - the filename/type/size card. */
function AttachmentPreviewBody({ attachment, preview }: AttachmentPreviewBodyProps) {
  if (preview.status === 'image' && preview.imageUrl) {
    return (
      <img
        src={preview.imageUrl}
        alt={attachment.name}
        className="jini-attachment-preview-image"
        onError={preview.onImageError}
      />
    );
  }
  if (preview.status === 'text') return <AttachmentTextPane preview={preview} />;
  return <AttachmentMetaCard attachment={attachment} sizeLabel={preview.sizeLabel} />;
}

function AttachmentTextPane({ preview }: { preview: AttachmentPreviewController }) {
  const t = useT();
  if (preview.textLoading) return <div className="jini-attachment-preview-loading">{t('Loading…')}</div>;
  return (
    <>
      <pre className="jini-attachment-preview-text">{preview.text?.content ?? ''}</pre>
      {preview.text?.truncated ? (
        <div className="jini-attachment-preview-truncated">
          {t('Preview truncated — this file is larger than the preview limit.')}
        </div>
      ) : null}
    </>
  );
}

function AttachmentMetaCard({ attachment, sizeLabel }: { attachment: ChatAttachment; sizeLabel: AttachmentPreviewController['sizeLabel'] }) {
  const t = useT();
  return (
    <div className="jini-attachment-preview-meta">
      <div className="jini-attachment-preview-meta-row">
        <span className="jini-attachment-preview-meta-label">{t('Name')}</span>
        <span>{attachment.name}</span>
      </div>
      <div className="jini-attachment-preview-meta-row">
        <span className="jini-attachment-preview-meta-label">{t('Type')}</span>
        <span>{looksLikeImageAttachment({ attachment: attachment }) ? t('Image') : t('File')}</span>
      </div>
      {sizeLabel ? (
        <div className="jini-attachment-preview-meta-row">
          <span className="jini-attachment-preview-meta-label">{t('Size')}</span>
          <span>{sizeLabel}</span>
        </div>
      ) : null}
      <div className="jini-attachment-preview-meta-note">{t('A preview is not available for this file.')}</div>
    </div>
  );
}

/** Previous/next side by side in the bottom-right corner, with the "2 / 5" position before them. */
function AttachmentPreviewNav({ navigation }: { navigation: AttachmentPreviewNavigation }) {
  const t = useT();
  return (
    <div className="jini-attachment-preview-nav">
      <span className="jini-attachment-preview-count" aria-live="polite">
        {t('{index} / {count}', { index: navigation.index + 1, count: navigation.count })}
      </span>
      <button
        type="button"
        className="jini-attachment-preview-step"
        onClick={navigation.onPrevious}
        title={t('Previous image')}
        aria-label={t('Previous image')}
      >
        <Icon name="chevron-left" size={18} />
      </button>
      <button
        type="button"
        className="jini-attachment-preview-step"
        onClick={navigation.onNext}
        title={t('Next image')}
        aria-label={t('Next image')}
      >
        <Icon name="chevron-right" size={18} />
      </button>
    </div>
  );
}

import { useEffect, useId, useLayoutEffect, useRef } from 'react';
import { TabBar } from '@jini-ai/ui/tab-strip';
import { InfoTip } from '@jini-ai/ui/admin-widgets';
import { useChatSettingsView, type ChatPermissionsPort, type ChatSettingsSection } from './ChatSettingsDialog.hooks.js';
import { ChatSettingsSegmented } from './ChatSettingsSegmented.js';

/** One switch row, with optional inline description and help beside the control and label.
 * The help trigger stays outside the label so tapping it never toggles the switch.
 * Earlier (owner) ⓘ tips floated away from their icon, so this row showed visible text only; on 2026-10-18 the owner approved per-option ⓘ help, which InfoTip now anchors to the icon.
 * Later that day radio groups moved to one ⓘ beside their legend; a switch keeps its own, which now
 * sits right after its label like the legend's (owner, 2026-10-21) instead of at the row's far edge. */
function SettingSwitch(required: {
  label: string; checked: boolean; disabled?: boolean | undefined; onChange: (checked: boolean) => void;
  description?: string | undefined; descriptionId: string; className?: string | undefined;
  tooltip?: string | undefined;
}, _optional: Record<string, never> = {}) {
  const inputId = useId();
  return <div className={['jini-chat-settings-row', required.className].filter(Boolean).join(' ')}>
    <input id={inputId} type="checkbox" role="switch" className="jini-checkbox jini-chat-settings-switch"
      checked={required.checked} disabled={required.disabled}
      aria-describedby={[required.description ? required.descriptionId : '', required.tooltip ? `${required.descriptionId}-tooltip` : ''].filter(Boolean).join(' ') || undefined}
      onChange={event => required.onChange(event.currentTarget.checked)} />
    <div className="jini-chat-settings-text">
      <span className="jini-chat-settings-label-row">
        <label htmlFor={inputId} className="jini-chat-settings-label">{required.label}</label>
        {required.tooltip && <InfoTip label={required.tooltip} descriptionId={`${required.descriptionId}-tooltip`} />}
      </span>
      {required.description && <p id={required.descriptionId} className="jini-chat-settings-description">{required.description}</p>}
    </div>
  </div>;
}

/** Advanced chat settings; the host supplies display actions, capabilities and persistence.
 * Native dialog semantics own modal focus containment; closing restores the opener.
 * Header and tabs stay fixed while only the active panel scrolls.
 */
export function ChatSettingsDialog(required: {
  open: boolean; onClose: () => void; displaySections: readonly ChatSettingsSection[];
  permissions: ChatPermissionsPort; t?: (key: string) => string;
}, _optional: Record<string, never> = {}) {
  const vm = useChatSettingsView(required);
  const dialogRef = useRef<HTMLDialogElement>(null), closeRef = useRef<HTMLButtonElement>(null), titleId = useId();
  const openerRef = useRef<Element | null>(null);
  useLayoutEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog || !required.open) return undefined;
    openerRef.current = document.activeElement;
    if (typeof dialog.showModal === 'function') { if (!dialog.open) dialog.showModal(); }
    else dialog.setAttribute('open', '');
    closeRef.current?.focus({ preventScroll: true });
    dialog.scrollTop = 0;
    return () => {
      if (typeof dialog.close === 'function') { if (dialog.open) dialog.close(); }
      else dialog.removeAttribute('open');
    };
  }, [required.open]);
  // Return focus to the opener from a passive cleanup: React's commit-time focus restore runs after
  // layout cleanups and would pull focus straight back to the closing dialog's × button.
  useEffect(() => {
    if (!required.open) return undefined;
    return () => {
      const opener = openerRef.current;
      if (opener instanceof HTMLElement && opener.isConnected) opener.focus({ preventScroll: true });
    };
  }, [required.open]);
  // Its own tip bounds: hosts mount this inside a narrow dock marked `data-jini-tip-bounds`, which
  // pushed the ⓘ bubbles of options outside the dock across the dialog, away from their icon.
  return <dialog ref={dialogRef} aria-labelledby={titleId} aria-modal="true" tabIndex={-1} data-jini-tip-bounds=""
    className="jini-dialog jini-chat-settings-dialog"
    onCancel={event => { event.preventDefault(); required.onClose(); }}
    onClick={event => {
      if (event.target !== event.currentTarget) return;
      const { clientX: x, clientY: y } = event, box = event.currentTarget.getBoundingClientRect();
      const horizontalOutside = x < box.left || x > box.right;
      const verticalOutside = y < box.top || y > box.bottom;
      if ((x === 0 && y === 0) || horizontalOutside || verticalOutside) required.onClose();
    }}>
    <header className="jini-chat-settings-header">
      <h2 id={titleId} className="jini-dialog-title">{vm.t('Chat settings')}</h2>
      <button ref={closeRef} type="button" className="jini-dialog-close jini-chat-settings-close"
        aria-label={vm.t('Close')} onClick={required.onClose}><span aria-hidden="true">×</span></button>
    </header>
    <TabBar tabs={vm.tabs} activeId={vm.tab} onChange={vm.setTab} ariaLabel={vm.t('Chat settings')} />
    <div className="jini-chat-settings-body" role="tabpanel"
      aria-label={vm.tab === 'display' ? vm.t('Display') : vm.t('Agent permissions')}>
      {vm.tab === 'display' ? vm.display.map(renderDisplaySection)
      : renderPermissions(vm)}
    </div>
  </dialog>;
}

function renderDisplaySection(section: ReturnType<typeof useChatSettingsView>["display"][number]) {
  if (section.radio) return (
    // One ⓘ for the whole choice, beside the legend (owner, 2026-10-18), not one per option. The
    // fieldset is named by the label span alone, so the tip's text never joins the group's name.
    <fieldset key={section.key} className="jini-chat-settings-group" aria-labelledby={section.label ? section.labelId : undefined}
      aria-describedby={[section.hint ? section.hintId : '', section.tooltip ? section.tooltipId : ''].filter(Boolean).join(' ') || undefined}>
      {section.label && <legend className="jini-chat-settings-legend">
        <span id={section.labelId}>{section.label}</span>
        {section.tooltip && <InfoTip label={section.tooltip} descriptionId={section.tooltipId} />}
      </legend>}
      {section.hint && <p id={section.hintId} className="jini-chat-settings-description jini-chat-settings-description--group">{section.hint}</p>}
      <ChatSettingsSegmented name={section.name} items={section.items} />
    </fieldset>
  );
  return <fieldset key={section.key} className="jini-chat-settings-group">
    {section.label && <legend className="jini-chat-settings-legend">{section.label}</legend>}
    {section.items.map(item => <SettingSwitch key={item.key} label={item.label} checked={!!item.checked}
      disabled={item.disabled} onChange={item.change} description={item.hint} descriptionId={item.hintId} tooltip={item.tooltip} />)}
  </fieldset>;
}

function renderPermissions(vm: ReturnType<typeof useChatSettingsView>) {
  return <>
    <p className="jini-chat-settings-note">{vm.t('Permission changes apply to the next run.')}</p>
    {vm.permissions.unavailableReason && <p className="jini-chat-settings-note">{vm.t(vm.permissions.unavailableReason)}</p>}
    <SettingSwitch className="jini-chat-settings-row--master" label={vm.master.label} checked={vm.master.checked}
      disabled={vm.master.disabled} onChange={checked => vm.master.onCheckedChange({ checked })}
      description={vm.master.description} descriptionId={vm.master.descriptionId} />
    <div className="jini-chat-settings-capabilities">
      {vm.capabilities.map(item => <SettingSwitch key={item.key} label={item.control.label} checked={item.control.checked}
        disabled={item.control.disabled} onChange={checked => item.control.onCheckedChange({ checked })}
        description={item.description} descriptionId={item.descriptionId} />)}
    </div>
    {vm.permissions.busy && <p role="status" className="jini-chat-settings-note">{vm.t('Saving…')}</p>}
    {vm.permissions.error && <p role="alert" className="jini-chat-settings-error">{vm.permissions.error}</p>}
  </>;
}

import { formatErrorForLog } from '@jini-ai/core';
/**
 * @module Composer
 *
 * The dumb, presentational half of the composer: takes a `useComposer()`
 * controller (headless state) plus a few UI-only props and renders the
 * textarea/attachment-tray/send-button chrome. Slot extraction points
 * (`ComposerPlusItem[]`, `leadingAccessories`, `footerAccessories`, the mention popover) are
 * generalized from OD's `ChatComposer.tsx` decomposition
 * (`ComposerPlusMenu`/`LibraryPicker`/`SessionModeToggle`-equivalent) per
 * `ADS-memory/reports/jini-port/recon/r4b-webui-design.md` §2/§3 — this component renders
 * the slots a host supplies; it does not itself know what a "library
 * picker" or "session mode" is.
 */
import { FolderChips } from './FolderChips.js';
import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ChangeEvent,
  type ClipboardEvent,
  type CSSProperties,
  type KeyboardEvent,
  type ReactNode,
  type RefObject,
} from 'react';
import { RemixIcon, useAgentHandle } from '@jini-ai/ui';
import { agentHandleProps, agentHandleSegment } from '@jini-ai/agentic';
import { useT } from '../hooks/context.js';
import { useComposerHistoryKeys } from '../hooks/useComposerHistoryKeys.hooks.js';
import { AttachmentTray } from './AttachmentTray.js';
import type { UseComposerResult } from '../hooks/useComposer.js';
import type { ComposerDiscoveryGroup, ComposerDiscoveryItem, ComposerDiscoveryOutcome, ComposerPlusItem, ComposerSlots } from '../slots.js';
import { ComposerDiscoveryMenu, ComposerSlashMenu } from './ComposerDiscovery.js';
import {
  appendComposerDiscovery,
  composerDiscoveryMenuPosition,
  composerSlashMenuPosition,
  filterComposerDiscovery,
  parseComposerSlashQuery,
  replaceComposerSlashTrigger,
  resolveComposerSlashInvocation,
  resolveComposerSlashKeyAction,
} from './composer-discovery.js';

export interface ComposerProps {
  /** Stable automation base; false suppresses every package-owned control handle. */
  agentHandle?: string | false | undefined;
  composer: UseComposerResult;
  onSend: () => void;
  disabled?: boolean;
  /** Disables submission without disabling draft editing or attachment controls. */
  sendDisabled?: boolean;
  /** Human-readable submission blocker, exposed on the Send button. */
  sendDisabledReason?: string;
  /** ID of the rendered blocker hint used as the Send button's description. */
  sendDisabledReasonId?: string;
  placeholder?: string;
  slots?: ComposerSlots;
  attachmentPicker?: {
    onFiles: (files: File[]) => void | Promise<void>;
    accept?: string;
    uploading?: boolean;
  };
  /**
   * A run is currently streaming. Swaps the trailing send button for a stop button in the same
   * position — same control an operator already has their attention on, rather than a second,
   * separately placed cancel affordance elsewhere in the pane. Always clickable when true,
   * regardless of `disabled`/`sendDisabled`/`composer.canSubmit`: those all gate *submitting a new
   * draft*, which has nothing to do with whether a caller may cancel the run already in flight.
   * Once the draft is submittable (and neither gate refuses it), Send comes back beside Stop, so a
   * message can go out mid-run without stopping anything.
   */
  running?: boolean;
  /** Cancels the in-flight run. Required when `running` is true; ignored otherwise. */
  onCancel?: () => void;
  /**
   * Cmd/Ctrl+Enter: optional host send shortcut. ChatPane shares the ordinary mid-run delivery
   * path so sending keeps the current run going. Without this callback the modifier falls
   * through to ordinary Enter, so a host that has not opted in keeps its previous behavior.
   */
  onInterrupt?: () => void;
  /**
   * Current working directory, or null/undefined when none is set yet. Paired with
   * `onChangeWorkingDirectory` — see that prop's own doc for why the trigger's presence is gated
   * on the handler rather than on this value.
   */
  workingDirectory?: string | null;
  /**
   * Confirms a directory typed into the working-directory popover. Its presence (not
   * `workingDirectory`'s) is what renders the folder-icon trigger in "popover" mode, next to the
   * attach/discovery button — for a host with no native picker to offer instead. A host that has
   * `ChatPaneWorkingDirectoryAccess` and wants the SAME trigger wired to the native dialog instead
   * passes `onPickWorkingDirectory` (below) in place of this prop, never both. A host relying on
   * `ChatPane`'s richer below-composer `WorkingDirPicker` passes neither, so it gets no second,
   * competing control here. This is the same working-directory value
   * `ChatPane`/`useChatPaneWorkingDirectory` already own — threaded one level deeper into this
   * presentational component, not a parallel concept.
   */
  onChangeWorkingDirectory?: (workingDirectory: string) => void;
  /**
   * Triggers the host's native OS directory dialog directly. Supplied instead of
   * `onChangeWorkingDirectory` (never alongside it) when the host has a
   * `ChatPaneWorkingDirectoryAccess` implementation and asked `ChatPane` to place the
   * working-directory control in the composer rather than below it
   * (`workingDirectoryControlPlacement="composer"`). Renders the exact same folder-icon trigger as
   * the popover mode — byte-identical `jini-composer-attach` styling, hit area, hover, and focus —
   * but clicking it calls this directly instead of opening the in-page text-input popover: there is
   * nothing to type, the native dialog IS the picker.
   */
  onPickWorkingDirectory?: () => void;
}

function reportComposerHostEffectFailure(effectName: string, error: unknown) {
  console.error(`[@jini-ai/chat] Composer ${effectName} host effect failed:`, formatErrorForLog({ error }));
}

/**
 * Invokes host code synchronously, then observes either its synchronous result or async failure.
 *
 * @param onResolved - Optional, called with the host's resolved (non-thrown/non-rejected) return
 * value — never called after a synchronous throw or an async rejection. Added for
 * `onDiscoverySelect`, whose {@link ComposerDiscoveryOutcome} return value the caller applies to
 * the draft; the two other host effects this function backs (`plusMenuItems.onSelect`,
 * `attachmentPicker.onFiles`) simply omit it, which reproduces their exact prior behavior.
 */
function runComposerHostEffect(
  effectName: string,
  effect: () => unknown,
  onSettled?: () => void,
  onResolved?: (result: unknown) => void,
) {
  let result: unknown;
  try {
    result = effect();
  } catch (error) {
    reportComposerHostEffectFailure(effectName, error);
    onSettled?.();
    return;
  }

  const asynchronous = result !== undefined;
  if (!asynchronous) {
    onResolved?.(result);
    onSettled?.();
  }
  void Promise.resolve(result)
    .then((resolved) => {
      if (asynchronous) onResolved?.(resolved);
    })
    .catch((error: unknown) => {
      reportComposerHostEffectFailure(effectName, error);
    })
    .finally(() => {
      if (asynchronous) onSettled?.();
    });
}

/**
 * Renders the controlled message composer and optional attachment picker.
 *
 * @complexity Time/space: O(n) in rendered attachments and supplied menu items.
 * @overallScore 100/100
 */
export function Composer({
  agentHandle,
  composer,
  onSend,
  disabled = false,
  sendDisabled = false,
  sendDisabledReason,
  sendDisabledReasonId,
  placeholder,
  slots,
  attachmentPicker,
  running = false,
  onCancel,
  onInterrupt,
  workingDirectory,
  onChangeWorkingDirectory,
  onPickWorkingDirectory,
}: ComposerProps) {
  const base = useAgentHandle({ agentHandle });
  const t = useT();
  const attachmentInputRef = useRef<HTMLInputElement | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);
  const discoveryEffectInFlightRef = useRef(false);
  /**
   * Mirrors `composer.draft` for the ONE place it must be read outside a render: inside
   * `notifyDiscovery`'s `onResolved` callback, which can fire after arbitrarily many re-renders
   * (nothing here disables the textarea while a host effect is in flight, so the user is free to
   * keep typing). Reassigned every render rather than via an effect — an effect would lag one
   * render behind the value it needs to be compared against at the exact moment the outcome
   * settles.
   */
  const draftRef = useRef(composer.draft);
  draftRef.current = composer.draft;
  const [discoveryMenuOpen, setDiscoveryMenuOpen] = useState(false);
  const [slashActiveIndex, setSlashActiveIndex] = useState(0);
  const [dismissedSlashDraft, setDismissedSlashDraft] = useState<string | null>(null);
  const [discoveryMenuPosition, setDiscoveryMenuPosition] = useState<CSSProperties>();
  const [slashMenuPosition, setSlashMenuPosition] = useState<CSSProperties>();
  const [workdirOpen, setWorkdirOpen] = useState(false);
  const [workdirDraft, setWorkdirDraft] = useState('');
  const [workdirPosition, setWorkdirPosition] = useState<CSSProperties>();
  const { discoveryGroups = [], leadingAccessories, footerLeadingAccessory, footerAccessories, plusMenuItems } = slots ?? {};
  const hasDiscoveryItems = discoveryGroups.some((group) => group.items.length > 0);
  const slash = slashPalette({ draft: composer.draft, groups: discoveryGroups, dismissedSlashDraft });
  const slashOpen = slash.open;
  const slashActiveOption = Math.min(slashActiveIndex, slash.matches.length - 1);
  const popovers: OpenPopovers = { discoveryMenuOpen, slashOpen, workdirOpen };

  const handleHistoryKey = useComposerHistoryKeys({ composer, textareaRef }, {
    popupOpen: anyPopoverOpen(popovers) || composer.mention.open,
  });

  function restoreComposerFocus() {
    textareaRef.current?.focus();
  }

  /**
   * Neither popover had any way to dismiss on an outside click — Escape worked (each already wires
   * its own keydown), but clicking away left them open with no affordance to close (bug report:
   * "no click-outside, owner is stuck once it opens"). `mousedown`, not `click`, so this settles
   * before the "+" trigger button's own `onToggle` fires on the SAME click — that click's target is
   * inside `.jini-composer-discovery` (the trigger lives there too), so it's correctly treated as
   * "inside" and left for `onToggle` to handle, not fought over by two competing handlers.
   *
   * Scoped by DOM lookup (`closest`/`querySelector`) off `textareaRef`, not new refs threaded
   * through `ComposerDiscovery.tsx`'s props — both popovers already carry stable classes/ids this
   * component doesn't otherwise need direct handles to.
   */
  useEffect(() => {
    if (!anyPopoverOpen(popovers)) return undefined;
    const textarea = textareaRef.current;
    const composerRoot = textarea?.closest('.jini-composer');
    if (!composerRoot) return undefined;

    function handleOutsideMouseDown(event: MouseEvent) {
      const target = event.target as Node | null;
      if (!target) return;
      if (discoveryMenuOpen && isOutside(composerRoot!, '.jini-composer-discovery', target)) setDiscoveryMenuOpen(false);
      if (slashOpen && !textarea!.contains(target) && isOutside(composerRoot!, '#jini-composer-slash-menu', target)) setDismissedSlashDraft(composer.draft);
      if (workdirOpen && isOutside(composerRoot!, '.jini-composer-workdir', target)) setWorkdirOpen(false);
    }

    document.addEventListener('mousedown', handleOutsideMouseDown);
    return () => document.removeEventListener('mousedown', handleOutsideMouseDown);
  }, [discoveryMenuOpen, slashOpen, workdirOpen, composer.draft]);

  /**
   * Anchors the "+" menu and slash palette to `.jini-composer`'s live on-screen rect via
   * `position: fixed` (see `composerDiscoveryMenuPosition`/`composerSlashMenuPosition`'s own doc
   * in `composer-discovery.ts` for the ancestor-clipping bug this fixes). `useLayoutEffect`, not
   * `useEffect`, so the measured position lands before the browser paints the just-opened popover
   * — otherwise the very first frame would flash at the CSS default (`position: absolute`)
   * position before snapping to the fixed one. Recomputed on scroll/resize while either popover is
   * open, matching `useAgentRuntimePicker.hooks.ts`'s identical popover-tracking idiom: the
   * composer's on-screen position can change under an open popover without it ever unmounting.
   */
  useLayoutEffect(() => {
    if (!anyPopoverOpen(popovers)) return undefined;
    const composerRoot = textareaRef.current?.closest('.jini-composer');
    if (!composerRoot) return undefined;

    function update() {
      const rect = composerRoot!.getBoundingClientRect();
      if (discoveryMenuOpen) setDiscoveryMenuPosition(composerDiscoveryMenuPosition({ composerRect: rect }));
      if (slashOpen) setSlashMenuPosition(composerSlashMenuPosition({ composerRect: rect }));
      // Shares the discovery menu's own anchor math (same left inset off `.jini-composer`) rather
      // than measuring the working-dir button's own rect — one less measurement to keep in sync,
      // and the two popovers already never open at once (each is gated on its own trigger).
      if (workdirOpen) setWorkdirPosition(composerDiscoveryMenuPosition({ composerRect: rect }));
    }

    update();
    window.addEventListener('scroll', update, true);
    window.addEventListener('resize', update);
    return () => {
      window.removeEventListener('scroll', update, true);
      window.removeEventListener('resize', update);
    };
  }, [discoveryMenuOpen, slashOpen, workdirOpen]);

  /**
   * `expectedDraft` is the draft as the user last saw it at the moment of selection — what the
   * host's effect was computed against. `argument` is passed only for a resolved `'invoke'` on a
   * `command`-bearing item (see `resolveComposerSlashInvocation`); omitted entirely for a plain
   * macro item, matching `ComposerDiscoverySelection.argument`'s own "absent means no command
   * grammar" contract.
   *
   * A `ComposerDiscoveryOutcome` the host returns replaces the draft — this is how a command whose
   * effect is computed asynchronously (e.g. composing agent-directed instruction text) gets to
   * write its result back, since nothing here can guess it in advance the way a plain item's own
   * `insertText` can. But nothing disables the textarea while that effect is in flight, so the
   * live draft (`draftRef.current`) may have moved on by the time it resolves. The outcome is
   * applied only if the live draft still matches `expectedDraft` exactly; otherwise it is
   * DISCARDED — silently overwriting keystrokes the user typed in the meantime would be worse than
   * dropping a result they can reselect.
   */
  function notifyDiscovery(
    item: ComposerDiscoveryItem,
    source: 'plus' | 'slash',
    expectedDraft: string,
    argument?: string | null,
  ) {
    const onDiscoverySelect = slots?.onDiscoverySelect;
    if (!onDiscoverySelect || discoveryEffectInFlightRef.current) return;
    discoveryEffectInFlightRef.current = true;
    runComposerHostEffect(
      'onDiscoverySelect',
      () => onDiscoverySelect({ item, source, ...(argument !== undefined ? { argument } : {}) }),
      () => {
        discoveryEffectInFlightRef.current = false;
      },
      (outcome) => {
        if (!outcome || typeof outcome !== 'object') return;
        const draft = (outcome as ComposerDiscoveryOutcome).draft;
        if (draft === undefined) return;
        if (draftRef.current !== expectedDraft) return;
        composer.setDraft(draft);
      },
    );
  }

  function selectSlashItem(item: ComposerDiscoveryItem) {
    const resolution = resolveComposerSlashInvocation({ draft: composer.draft, item });
    if (!resolution) return;

    if (resolution.type === 'complete') {
      // The command word is ambiguous or its argument is still missing — finish the trigger and
      // keep the palette open for further typing. No host effect fires: nothing was invoked yet.
      composer.setDraft(resolution.draft);
      setDismissedSlashDraft(null);
      restoreComposerFocus();
      return;
    }

    let expectedDraft = composer.draft;
    if (!item.command) {
      expectedDraft = replaceComposerSlashTrigger({ draft: composer.draft, insertText: item.insertText ?? item.label });
      composer.setDraft(expectedDraft);
    }
    setDismissedSlashDraft(null);
    notifyDiscovery(item, 'slash', expectedDraft, resolution.argument);
    restoreComposerFocus();
  }

  function selectPlusItem(item: ComposerDiscoveryItem) {
    const expectedDraft = item.insertText ? appendComposerDiscovery({ draft: composer.draft, insertText: item.insertText }) : composer.draft;
    if (item.insertText) composer.setDraft(expectedDraft);
    setDiscoveryMenuOpen(false);
    notifyDiscovery(item, 'plus', expectedDraft);
    restoreComposerFocus();
  }

  /** Opens the working-directory popover, seeding its draft from the live value so a reopen never
   *  shows a stale edit from a previously-dismissed attempt. */
  function toggleWorkdir() {
    if (!workdirOpen) setWorkdirDraft(workingDirectory ?? '');
    setWorkdirOpen((open) => !open);
  }

  /** Confirms the popover's draft. Blank input is treated as "no change" (closes without calling
   *  the host) rather than clearing the directory — this lightweight control has no clear
   *  affordance of its own; `onChangeWorkingDirectory`'s own doc points to the native picker
   *  (`ChatPaneWorkingDirectoryAccess`) that does support clearing. */
  function confirmWorkdir() {
    const trimmed = workdirDraft.trim();
    if (trimmed) onChangeWorkingDirectory?.(trimmed);
    setWorkdirOpen(false);
  }

  /** Palette navigation wins over history and Enter while the slash palette is open; true when it consumed the key. */
  function handleSlashKey(event: KeyboardEvent<HTMLTextAreaElement>): boolean {
    if (!slashOpen) return false;
    const action = resolveComposerSlashKeyAction({ key: event.key, shiftKey: event.shiftKey });
    if (action.type === 'none') return false;
    event.preventDefault();
    if (action.type === 'move') {
      setSlashActiveIndex((current) => (current + action.offset + slash.matches.length) % slash.matches.length);
    } else if (action.type === 'select') {
      selectSlashItem(slash.matches[slashActiveOption]!.item);
    } else {
      setDismissedSlashDraft(composer.draft);
    }
    return true;
  }

  function submitFromEnter(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (disabled || !composer.canSubmit) return;
    // Cmd/Ctrl+Enter uses the host shortcut; ChatPane routes it through the ordinary send guards.
    // `sendDisabled` is deliberately NOT consulted here: hosts can offer a shortcut while a run
    // itself blocks ordinary sends. ChatPane queues or delivers live without cancelling the run.
    if ((event.metaKey || event.ctrlKey) && onInterrupt) {
      onInterrupt();
      return;
    }
    if (!sendDisabled) onSend();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    if (event.nativeEvent.isComposing) return;
    if (handleSlashKey(event)) return;
    if (handleHistoryKey(event)) return;
    if (event.key !== 'Enter' || event.shiftKey) return;
    event.preventDefault();
    submitFromEnter(event);
  }

  function handleAttachmentChange(event: ChangeEvent<HTMLInputElement>) {
    const files = Array.from(event.target.files ?? []);
    event.target.value = '';
    if (files.length > 0 && attachmentPicker) {
      runComposerHostEffect('attachmentPicker.onFiles', () => attachmentPicker.onFiles(files));
    }
  }

  /**
   * A screenshot or a Finder-copied video pasted into the textarea previously vanished with no
   * feedback: the browser's default paste has nothing to do with a `File` on the clipboard (it only
   * inserts `text/plain`, which a file-only clipboard entry never carries), so the keystroke was a
   * silent no-op — no chip, no `/api/attachments` call, nothing. This is the paste-side counterpart
   * to `handleAttachmentChange` (the file-input path) and `useChatPaneFileDrop` (the drag-and-drop
   * path); all three now reach `attachmentPicker.onFiles` the same way.
   *
   * `preventDefault` only when `files.length > 0` — an ordinary text paste (the overwhelmingly
   * common case) is left to the browser's own default handling untouched.
   */
  function handleAttachmentPaste(event: ClipboardEvent<HTMLTextAreaElement>) {
    if (!attachmentPicker) return;
    const files = Array.from(event.clipboardData?.files ?? []);
    if (files.length === 0) return;
    event.preventDefault();
    runComposerHostEffect('attachmentPicker.onFiles', () => attachmentPicker.onFiles(files));
  }

  return (
    <div className="jini-composer">
      <AccessorySlot className="jini-composer-leading">{leadingAccessories}</AccessorySlot>
      <div className="jini-composer-attachments">
        <AttachmentTray agentHandle={base} attachments={composer.attachments} onRemove={composer.removeAttachment} uploading={attachmentPicker?.uploading === true} />
        <FolderChips agentHandle={base} folders={composer.folders} onRemove={composer.removeFolder} />
      </div>
      <textarea
        {...agentHandleProps({}, { base, action: 'draft', role: 'field', label: t('Message draft') })}
        ref={textareaRef}
        className="jini-composer-input"
        value={composer.draft}
        placeholder={placeholder ?? t('Send a message…')}
        disabled={disabled}
        onChange={(e) => {
          composer.setDraft(e.target.value);
          setSlashActiveIndex(0);
          setDismissedSlashDraft(null);
        }}
        onKeyDown={handleKeyDown}
        // Draft persistence is debounced (see `DRAFT_PERSIST_DEBOUNCE_MS`); leaving the field is a
        // natural point to make it durable now.
        onBlur={() => composer.flushDraft?.()}
        onPaste={handleAttachmentPaste}
        {...slashTextareaAria(slashOpen, slashActiveOption)}
        rows={3}
      />
      {slashOpen ? (
        <ComposerSlashMenu
          base={base}
          matches={slash.matches}
          activeIndex={slashActiveOption}
          onSelect={selectSlashItem}
          showFilterHint={slash.showFilterHint}
          style={slashMenuPosition}
          t={t}
        />
      ) : null}
      <div className="jini-composer-footer">
        <ComposerAttachButton base={base} attachmentPicker={attachmentPicker} hidden={hasDiscoveryItems} disabled={disabled} inputRef={attachmentInputRef} onChange={handleAttachmentChange} t={t} />
        <ComposerDiscoveryMenu
          base={base}
          groups={discoveryGroups}
          open={discoveryMenuOpen}
          disabled={disabled}
          {...(attachmentPicker ? { attachmentPicker } : {})}
          attachmentInputRef={attachmentInputRef}
          onToggle={() => setDiscoveryMenuOpen((open) => !open)}
          onClose={() => setDiscoveryMenuOpen(false)}
          onSelect={selectPlusItem}
          onAttachmentChange={handleAttachmentChange}
          style={discoveryMenuPosition}
          t={t}
        />
        <AccessorySlot className="jini-composer-footer-leading">{footerLeadingAccessory}</AccessorySlot>
        <ComposerWorkdirControl
          base={base}
          workingDirectory={workingDirectory}
          onChangeWorkingDirectory={onChangeWorkingDirectory}
          onPickWorkingDirectory={onPickWorkingDirectory}
          disabled={disabled}
          open={workdirOpen}
          draft={workdirDraft}
          position={workdirPosition}
          onToggle={toggleWorkdir}
          onDraftChange={setWorkdirDraft}
          onConfirm={confirmWorkdir}
          onClose={() => setWorkdirOpen(false)}
          t={t}
        />
        {/* One group, so a footer too narrow for everything wraps the picker and send to their own
            line together instead of leaving send alone on it (see the styles' footer rules). */}
        <div className="jini-composer-footer-trailing">
          <AccessorySlot className="jini-composer-footer-accessories">{footerAccessories}</AccessorySlot>
          <ComposerPlusMenu base={base} items={plusMenuItems} t={t} />
          <ComposerSendGroup
            base={base}
            running={running}
            disabled={disabled}
            sendDisabled={sendDisabled}
            canSubmit={composer.canSubmit}
            onSend={onSend}
            onCancel={onCancel}
            sendDisabledReason={sendDisabledReason}
            sendDisabledReasonId={sendDisabledReasonId}
            t={t}
          />
        </div>
      </div>
    </div>
  );
}

type Translate = ReturnType<typeof useT>;

interface OpenPopovers {
  discoveryMenuOpen: boolean;
  slashOpen: boolean;
  workdirOpen: boolean;
}

function anyPopoverOpen({ discoveryMenuOpen, slashOpen, workdirOpen }: OpenPopovers): boolean {
  return discoveryMenuOpen || slashOpen || workdirOpen;
}

/** A missing popover element counts as outside, so a stale open flag still closes. */
function isOutside(composerRoot: Element, selector: string, target: Node): boolean {
  return !composerRoot.querySelector(selector)?.contains(target);
}

/** Slash palette state derived from the live draft. */
function slashPalette({ draft, groups, dismissedSlashDraft }: { draft: string; groups: readonly ComposerDiscoveryGroup[]; dismissedSlashDraft: string | null }) {
  const query = parseComposerSlashQuery({ draft });
  const matches = query === null ? [] : filterComposerDiscovery({ groups, query });
  return {
    matches,
    open: matches.length > 0 && dismissedSlashDraft !== draft,
    /**
     * A bare "/" intentionally matches every item (`matchesFuzzyCommand`'s own doc) so the palette
     * doubles as a browse-everything view — but with nothing typed yet, nothing on screen tells a
     * first-time user that continuing to type narrows it, and a fuzzy substring match against full
     * descriptions stays broad for the first character or two regardless (owner-reported "it doesn't
     * narrow" — narrowing DOES fire on every keystroke, this is the one state where there's no visual
     * cue that it will). Shown only here, not once the user has started typing a real query — at that
     * point the shrinking list is its own feedback.
     */
    showFilterHint: query !== null && query.command === '' && query.argument === null,
  };
}

function slashTextareaAria(slashOpen: boolean, activeOption: number) {
  if (!slashOpen) return { 'aria-controls': undefined, 'aria-expanded': false, 'aria-activedescendant': undefined };
  return { 'aria-controls': 'jini-composer-slash-menu', 'aria-expanded': true, 'aria-activedescendant': `jini-composer-slash-option-${activeOption}` };
}

function AccessorySlot({ className, children }: { className: string; children: ReactNode }) {
  return children ? <div className={className}>{children}</div> : null;
}

/** The plain paperclip, shown only when there is no "+" discovery menu to carry attaching instead. */
function ComposerAttachButton({ base, attachmentPicker, hidden, disabled, inputRef, onChange, t }: {
  base: string | undefined;
  attachmentPicker: ComposerProps['attachmentPicker'];
  hidden: boolean;
  disabled: boolean;
  inputRef: RefObject<HTMLInputElement | null>;
  onChange: (event: ChangeEvent<HTMLInputElement>) => void;
  t: Translate;
}) {
  if (!attachmentPicker || hidden) return null;
  const uploading = attachmentPicker.uploading;
  const label = t(uploading ? 'Attaching files…' : 'Attach files');
  return (
    <div className="jini-composer-attachment-picker">
      <input
        ref={inputRef}
        className="jini-composer-file-input"
        data-testid="composer-attachment-input"
        type="file"
        multiple
        aria-label={t('Attach files')}
        accept={attachmentPicker.accept}
        disabled={disabled || uploading}
        onChange={onChange}
      />
      <button
        type="button"
        {...agentHandleProps({}, { base, action: 'attach', role: 'button', label })}
        className="jini-composer-attach"
        disabled={disabled || uploading}
        onClick={() => inputRef.current?.click()}
        title={label}
        aria-label={label}
      >
        <RemixIcon
          name={uploading ? 'refresh-line' : 'add-line'}
          size={20}
          {...(uploading ? { className: 'jini-composer-spinner' } : {})}
        />
      </button>
    </div>
  );
}

function ComposerWorkdirControl({ base, workingDirectory, onChangeWorkingDirectory, onPickWorkingDirectory, disabled, open, draft, position, onToggle, onDraftChange, onConfirm, onClose, t }: {
  base: string | undefined;
  workingDirectory: string | null | undefined;
  onChangeWorkingDirectory: ComposerProps['onChangeWorkingDirectory'];
  onPickWorkingDirectory: ComposerProps['onPickWorkingDirectory'];
  disabled: boolean;
  open: boolean;
  draft: string;
  position: CSSProperties | undefined;
  onToggle: () => void;
  onDraftChange: (draft: string) => void;
  onConfirm: () => void;
  onClose: () => void;
  t: Translate;
}) {
  if (!onChangeWorkingDirectory && !onPickWorkingDirectory) return null;
  return (
    <div className="jini-composer-workdir" data-testid="composer-workdir">
      <button
        type="button"
        className="jini-composer-attach"
        {...agentHandleProps({}, { base, action: 'workdir', role: 'button', label: t('Set working directory') })}
        data-testid="composer-workdir-trigger"
        disabled={disabled}
        onClick={onPickWorkingDirectory ? () => onPickWorkingDirectory() : onToggle}
        {...(onPickWorkingDirectory ? {} : { 'aria-haspopup': 'dialog' as const, 'aria-expanded': open })}
        title={workingDirectory ?? t('Set working directory')}
        aria-label={
          workingDirectory
            ? t('Working directory: {dir}', { dir: workingDirectory })
            : t('Set working directory')
        }
      >
        <RemixIcon name="folder-line" size={20} />
      </button>
      {!onPickWorkingDirectory && open ? (
        <div
          className="jini-composer-workdir-panel"
          data-testid="composer-workdir-panel"
          role="dialog"
          aria-label={t('Working directory')}
          style={position}
        >
          <input
            type="text"
            className="jini-composer-workdir-input"
            {...agentHandleProps({}, { base, action: 'workdir-path', role: 'field', label: t('Working directory path') })}
            data-testid="composer-workdir-input"
            value={draft}
            onChange={(e) => onDraftChange(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                e.preventDefault();
                onConfirm();
                return;
              }
              if (e.key === 'Escape') {
                e.preventDefault();
                onClose();
              }
            }}
            placeholder={t('Working directory path')}
            aria-label={t('Working directory path')}
            autoFocus
          />
          <button
            type="button"
            className="jini-composer-workdir-confirm"
            {...agentHandleProps({}, { base, action: 'workdir-set', role: 'button', label: t('Set working directory') })}
            data-testid="composer-workdir-confirm"
            onClick={onConfirm}
          >
            {t('Set')}
          </button>
        </div>
      ) : null}
    </div>
  );
}

function ComposerPlusMenu({ base, items, t }: { base: string | undefined; items: readonly ComposerPlusItem[] | undefined; t: Translate }) {
  if (!items || items.length === 0) return null;
  return (
    <div className="jini-composer-plus-menu">
      {items.map((item) => (
        <button
          key={item.id}
          type="button"
          {...agentHandleProps({}, { base, action: `extra-${agentHandleSegment({ value: item.id })}`, role: 'button', label: t(item.label) })}
          className="jini-composer-plus-item"
          onClick={() => runComposerHostEffect('plusMenuItems.onSelect', () => item.onSelect())}
          title={t(item.label)}
        >
          {item.icon ?? null}
          <span>{t(item.label)}</span>
        </button>
      ))}
    </div>
  );
}

function ComposerSendGroup({ base, running, disabled, sendDisabled, canSubmit, onSend, onCancel, sendDisabledReason, sendDisabledReasonId, t }: {
  base: string | undefined;
  running: boolean;
  disabled: boolean;
  sendDisabled: boolean;
  canSubmit: boolean;
  onSend: () => void;
  onCancel: (() => void) | undefined;
  sendDisabledReason: string | undefined;
  sendDisabledReasonId: string | undefined;
  t: Translate;
}) {
  const canSend = !disabled && !sendDisabled && canSubmit;
  return (
    // While a run streams, Send sits beside Stop once there is something to send: a message
    // sent mid-run goes to the running agent (or next, if it cannot take it now). One group so
    // the footer's space-between keeps the two together at the trailing edge.
    <span className="jini-composer-send-group">
      {!running || canSend ? (
        <button {...agentHandleProps({}, { base, action: 'send', role: 'button', label: t('Send') })} type="button" className="jini-composer-send" disabled={!canSend} onClick={onSend} title={sendDisabledReason ?? t('Send')} aria-label={t('Send')} aria-describedby={sendDisabledReasonId}>
          <RemixIcon name="send-plane-2-line" size={16} />
        </button>
      ) : null}
      {running ? (
        <button {...agentHandleProps({}, { base, action: 'stop', role: 'button', label: t('Stop run') })} type="button" className="jini-composer-send jini-composer-send--stop" onClick={onCancel} title={t('Stop run')} aria-label={t('Stop run')}>
          <RemixIcon name="stop-fill" size={14} />
        </button>
      ) : null}
    </span>
  );
}

import type { ChangeEvent, CSSProperties, RefObject } from 'react';
import { RemixIcon } from '@jini-ai/ui';
import { agentHandleProps, agentHandleSegment } from '@jini-ai/agentic';
import type { ComposerDiscoveryGroup, ComposerDiscoveryItem } from '../slots.js';
import type { ComposerDiscoveryMatch } from './composer-discovery.js';

interface AttachmentPicker {
  onFiles: (files: File[]) => void | Promise<void>;
  accept?: string;
  uploading?: boolean;
}

export interface ComposerDiscoveryMenuProps {
  base?: string | undefined;
  groups: readonly ComposerDiscoveryGroup[];
  open: boolean;
  disabled: boolean;
  attachmentPicker?: AttachmentPicker;
  attachmentInputRef: RefObject<HTMLInputElement | null>;
  onToggle: () => void;
  onClose: () => void;
  onSelect: (item: ComposerDiscoveryItem) => void;
  onAttachmentChange: (event: ChangeEvent<HTMLInputElement>) => void;
  t: (key: string) => string;
  /** Viewport-fixed position computed by `Composer.tsx` (see `composerDiscoveryMenuPosition` in
   *  `composer-discovery.ts`) so the popover escapes any `overflow: hidden` ancestor between the
   *  composer and the page root. `undefined` for the one synchronous render before that
   *  measurement lands, during which the reference stylesheet's `position: absolute` default
   *  still applies — inline `style` always wins once it is set. */
  style?: CSSProperties | undefined;
}

/** Generic grouped add-menu; the host owns all inventory labels and items. */
export function ComposerDiscoveryMenu(props: ComposerDiscoveryMenuProps) {
  const hasItems = props.groups.some((group) => group.items.length > 0);
  if (!hasItems) return null;

  return (
    <div
      className="jini-composer-discovery"
      onKeyDown={(event) => {
        if (event.key !== 'Escape' || !props.open) return;
        event.preventDefault();
        props.onClose();
      }}
    >
      {props.attachmentPicker ? (
        <input
          ref={props.attachmentInputRef}
          className="jini-composer-file-input"
          data-testid="composer-attachment-input"
          type="file"
          multiple
          aria-label={props.t('Attach files')}
          accept={props.attachmentPicker.accept}
          disabled={props.disabled || props.attachmentPicker.uploading}
          onChange={props.onAttachmentChange}
        />
      ) : null}
      <button
        type="button"
        {...agentHandleProps({}, { base: props.base, action: 'discovery', role: 'button', label: props.t('Add context') })}
        className="jini-composer-attach"
        disabled={props.disabled}
        onClick={props.onToggle}
        aria-expanded={props.open}
        aria-haspopup="menu"
        title={props.t('Add context')}
        aria-label={props.t('Add context')}
      >
        <RemixIcon name="add-line" size={20} />
      </button>
      {props.open ? (
        <div className="jini-composer-discovery-menu" style={props.style} role="menu" aria-label={props.t('Add context')}>
          {props.attachmentPicker ? (
            <div className="jini-composer-discovery-group" role="group" aria-label={props.t('Files')}>
              <span className="jini-composer-discovery-group-label">{props.t('Files')}</span>
              <button
                type="button"
                role="menuitem"
                {...agentHandleProps({}, { base: props.base, action: 'attach', role: 'button', label: props.t('Attach files') })}
                className="jini-composer-discovery-item"
                disabled={props.disabled || props.attachmentPicker.uploading}
                onClick={() => {
                  props.onClose();
                  props.attachmentInputRef.current?.click();
                }}
              >
                {props.t(props.attachmentPicker.uploading ? 'Attaching files…' : 'Attach files')}
              </button>
            </div>
          ) : null}
          {props.groups.map((group) =>
            group.items.length > 0 ? (
              <div key={group.id} className="jini-composer-discovery-group" role="group" aria-label={props.t(group.label)}>
                <span className="jini-composer-discovery-group-label">{props.t(group.label)}</span>
                {group.items.map((item) => {
                  const description = item.description ? props.t(item.description) : undefined;
                  const descriptionId = description ? `jini-composer-discovery-desc-${item.id}` : undefined;
                  return (
                    <button
                      key={item.id}
                      type="button"
                      role="menuitem"
                      {...agentHandleProps({}, { base: props.base, action: `discover-${agentHandleSegment({ value: group.id })}-${agentHandleSegment({ value: item.id })}`, role: 'button', label: props.t(item.label) })}
                      className="jini-composer-discovery-item"
                      aria-describedby={descriptionId}
                      onClick={() => props.onSelect(item)}
                    >
                      <span>{props.t(item.label)}</span>
                      {/* Kept compact by design (label only) — the full description is a real
                          hover/focus tooltip (`.jini-composer-discovery-description`, styled to
                          match the popover itself — see its own doc in styles.ts for why NOT a bare
                          `title` attribute), reachable for assistive tech via `aria-describedby`
                          whether or not anything is hovering. */}
                      {description ? (
                        <small id={descriptionId} className="jini-composer-discovery-description">
                          {description}
                        </small>
                      ) : null}
                    </button>
                  );
                })}
              </div>
            ) : null,
          )}
        </div>
      ) : null}
    </div>
  );
}

export interface ComposerSlashMenuProps {
  base?: string | undefined;
  matches: readonly ComposerDiscoveryMatch[];
  activeIndex: number;
  onSelect: (item: ComposerDiscoveryItem) => void;
  /** True only for a bare "/" (see `Composer.tsx`'s own doc on `showSlashFilterHint`) — shows a
   *  one-line "keep typing to narrow" cue above the options, since that's the one state where
   *  nothing else on screen signals that typing filters the list. */
  showFilterHint?: boolean;
  t: (key: string) => string;
  /** Viewport-fixed position computed by `Composer.tsx` (see `composerSlashMenuPosition` in
   *  `composer-discovery.ts`) — same escape-the-ancestor-clip mechanism as
   *  {@link ComposerDiscoveryMenuProps.style}. */
  style?: CSSProperties | undefined;
}

/** Keyboard navigation is owned by Composer so focus stays in the textarea. */
export function ComposerSlashMenu(props: ComposerSlashMenuProps) {
  if (props.matches.length === 0) return null;

  return (
    <div
      id="jini-composer-slash-menu"
      className="jini-composer-slash-menu"
      style={props.style}
      role="listbox"
      aria-label={props.t('Composer commands')}
    >
      {props.showFilterHint ? (
        // `role="presentation"` opts this out of the listbox's own "children are options" ARIA
        // expectation explicitly, rather than leaving an unmarked stray `<div>` for assistive tech
        // to guess about — same escape hatch real combobox implementations use for a "no results"
        // row. Reuses `.jini-composer-discovery-group-label`'s existing look (faint, small,
        // uppercase) instead of introducing a new visual style for one hint line.
        <div className="jini-composer-discovery-group-label" role="presentation">
          {props.t('Keep typing to narrow the list')}
        </div>
      ) : null}
      {props.matches.map((match, index) => {
        const description = props.t(match.item.description ?? match.groupLabel);
        const descriptionId = `jini-composer-slash-option-${index}-desc`;
        return (
          <button
            key={`${match.groupId}:${match.item.id}`}
            id={`jini-composer-slash-option-${index}`}
            {...agentHandleProps({}, { base: props.base, action: `command-${agentHandleSegment({ value: match.groupId })}-${agentHandleSegment({ value: match.item.id })}`, role: 'button', label: props.t(match.item.label) })}
            type="button"
            role="option"
            aria-selected={index === props.activeIndex}
            aria-describedby={descriptionId}
            className={`jini-composer-discovery-item${index === props.activeIndex ? ' is-active' : ''}`}
            onMouseDown={(event) => event.preventDefault()}
            onClick={() => props.onSelect(match.item)}
          >
            <span>
              {props.t(match.item.label)}
              {match.item.argument ? (
                <code className="jini-composer-slash-argument"> {match.item.argument.placeholder}</code>
              ) : null}
              {match.item.needsConfirmation ? (
                <small className="jini-composer-slash-confirm-badge"> {props.t('Confirm')}</small>
              ) : null}
            </span>
            {/* Compact row, real hover/focus tooltip — see the matching doc on the "+" menu's
                identical change just above. */}
            <small id={descriptionId} className="jini-composer-discovery-description">
              {description}
            </small>
          </button>
        );
      })}
    </div>
  );
}

import { formatErrorForLog } from '@jini-ai/core';
import { useRef, useState } from 'react';
import { MAX_CONVERSATION_TITLE_LENGTH } from '../../core/conversation-title.js';
import { useT } from '../hooks/context.js';

export interface ConversationTitleEditorProps {
  title: string | null;
  onCommit: (title: string) => void | Promise<void>;
  onCancel: () => void;
  className?: string;
  'data-testid'?: string;
}

/**
 * Shared inline rename lifecycle. Enter/blur save once; Escape, empty and unchanged drafts cancel.
 * Snapshots the raw title on mount so a background title refresh cannot become a user edit.
 * Host failures are reported without leaving a rejected promise unhandled.
 * @complexity O(n) time/space to trim a draft of n code units; the saved title is bounded.
 * @example <ConversationTitleEditor title={title} onCommit={rename} onCancel={close} />
 */
export function ConversationTitleEditor({ title, onCommit, onCancel, className = 'jini-conv-rename', 'data-testid': testId }: ConversationTitleEditorProps) {
  const t = useT();
  const original = useRef(title ?? '');
  const [draft, setDraft] = useState(original.current);
  const finished = useRef(false);

  // Enter/Escape can unmount a focused input and cause blur; only the first completion may act.
  const finish = async ({ cancel = false } = {}) => {
    if (finished.current) return;
    finished.current = true;
    const next = draft.trim().slice(0, MAX_CONVERSATION_TITLE_LENGTH);
    if (cancel || !next || draft === original.current) {
      onCancel();
      return;
    }
    try {
      await onCommit(next);
    } catch (error) {
      console.error('[@jini-ai/chat] ConversationTitleEditor onCommit host effect failed:', formatErrorForLog({ error }));
    }
  };

  return <input
    autoFocus
    className={className}
    aria-label={t('Rename chat')}
    data-testid={testId}
    maxLength={MAX_CONVERSATION_TITLE_LENGTH}
    value={draft}
    onChange={(event) => setDraft(event.currentTarget.value)}
    onBlur={() => { void finish(); }}
    onKeyDown={(event) => {
      if (event.key === 'Enter' || event.key === 'Escape') {
        event.preventDefault();
        event.stopPropagation();
        void finish({ cancel: event.key === 'Escape' });
      }
    }}
  />;
}

export interface ConversationTitleProps {
  title: string | null;
  displayTitle: string;
  onRename: (title: string) => void | Promise<void>;
  disabled?: boolean;
}

/** Clickable title using the same editor as ConversationList; a host keys it by conversation ID.
 * @complexity O(1) outside the shared editor's draft normalization.
 * @example <ConversationTitle key={id} title={rawTitle} displayTitle={label} onRename={rename} />
 */
export function ConversationTitle({ title, displayTitle, onRename, disabled = false }: ConversationTitleProps) {
  const t = useT();
  const [editing, setEditing] = useState(false);
  return editing ? <ConversationTitleEditor title={title} onCancel={() => setEditing(false)} onCommit={(next) => {
    setEditing(false);
    return onRename(next);
  }} /> : <button type="button" className="jini-conv-title-button" aria-label={t('Rename chat')}
    title={displayTitle} disabled={disabled} onClick={() => setEditing(true)}>{displayTitle}</button>;
}

/**
 * @module Markdown
 *
 * A pocket-sized markdown renderer for assistant chat message text. No
 * `dangerouslySetInnerHTML` — output is a tree of typed React elements, so
 * untrusted text can't smuggle markup through.
 *
 * DELIBERATE SUBSET, not a full port: OD's `runtime/markdown.tsx` (734
 * lines) additionally handles a code-comment directive syntax — reasonable
 * follow-up work, left out here since no host has a concrete requirement
 * for it yet. Fenced code blocks DO now carry a per-block copy button
 * (`CopyCodeButton` below), reusing `useCopyToClipboard`
 * (`../hooks/useCopyToClipboard.js`) — the same hook `MessageRow.tsx`'s
 * per-message copy button is built on, so both share one secure-context/
 * fallback implementation. The two stay separate *components*, not one
 * shared button: a per-message copy sits in a `.jini-message-actions` row
 * alongside future branch/feedback siblings, while a per-block copy sits
 * on the code block itself and copies only that block's own source, not
 * the whole message — different placement and different copy scope, so a
 * shared component would mean threading scope-specific behavior through a
 * control neither call site actually wants generic. This renderer now
 * also covers GFM pipe tables — ported from OD's `runtime/markdown.tsx`
 * (`splitTableCells`/`parseTableAlignRow`/table block parsing and
 * rendering), including a wide-table pop-out (`TableBlock` below): a table
 * whose rendered width exceeds its own box gets an "Expand table" affordance
 * that reopens it full-size in a native `<dialog>`, mirroring the same
 * overflow-detection + `<dialog>` pattern one existing downstream admin host
 * already built for its own "Show in modal" affordance on other overflowing
 * content (a matched `useOverflowDetection` hook + native-`<dialog>` modal
 * pair) — kept as a *self-contained* copy here rather than an import, since
 * `@jini-ai/chat` cannot depend on a downstream host package, and every
 * other Jini host gets the same affordance this way. Everything else this
 * renderer covers:
 * ATX headings (`#`…`###`), fenced code blocks, ordered/unordered lists,
 * blockquotes, a horizontal rule, paragraphs, and inline `` `code` ``/
 * `**bold**`/`*italic*`/`[label](url)` links/bare autolinks — including inside table cells, via
 * the same `renderInline` pass every other block uses. TODO(follow-up): port
 * the code-comment directive syntax once a host needs it.
 */
import { Fragment, useEffect, useRef, useState, type ReactNode, type RefObject } from 'react';
import { useCopyToClipboard } from '../hooks/useCopyToClipboard.js';
import { useT } from '../hooks/context.js';
import { Icon } from './Icon.js';

export interface MarkdownProps {
  children: string;
}

type TableAlign = 'left' | 'right' | 'center' | null;

type Block =
  | { kind: 'p'; text: string }
  | { kind: 'h'; level: 1 | 2 | 3; text: string }
  | { kind: 'ul'; items: string[] }
  | { kind: 'ol'; start: number; items: string[] }
  | { kind: 'bq'; text: string }
  | { kind: 'code'; lang: string | null; body: string }
  | { kind: 'table'; aligns: TableAlign[]; headers: string[]; rows: string[][] }
  | { kind: 'hr' };

export function Markdown({ children }: MarkdownProps) {
  const blocks = parseBlocks(children);
  return (
    <>
      {blocks.map((block, i) => (
        <Fragment key={i}>{renderBlock(block)}</Fragment>
      ))}
    </>
  );
}

// GFM pipe-table cell split, ported logic-for-logic from OD's
// `runtime/markdown.tsx`. Tokenizes rather than a naive `split('|')`
// so it can honor three cell-content rules without placeholder substitution:
// `\|` is a literal pipe inside a cell, a `|` inside a backtick code span is
// cell content rather than a column boundary, and a single optional leading
// `|` plus an unescaped trailing `|` are row terminators, not empty cells.
// Always returns at least one cell (an empty row yields `['']`).
const TABLE_ROW_LEAD = /^ *\|?/;
const TABLE_CELL_TOKEN = /\\\||`|\||[^`|\\]+|\\/g;

function splitTableCells(line: string): string[] {
  const cells: string[] = [];
  let cur = '';
  let inCode = false;
  for (const token of line.replace(TABLE_ROW_LEAD, '').match(TABLE_CELL_TOKEN) ?? []) {
    if (token === '|' && !inCode) {
      cells.push(cur.trim());
      cur = '';
      continue;
    }
    if (token === '`') inCode = !inCode;
    cur += token === '\\|' ? '|' : token;
  }
  const tail = cur.trim();
  if (cells.length === 0 || tail !== '') cells.push(tail);
  return cells;
}

const TABLE_ALIGN_CELL = /^:?-+:?$/;
// Every cell `TABLE_ALIGN_CELL` accepts starts and ends with `:` or `-`, so its
// first + last character is always exactly one of these four keys.
const COLUMN_ALIGN = { '::': 'center', '-:': 'right', ':-': 'left', '--': null } as const;

// Recognizes a GFM alignment row (`| --- | :---: | ---: |`) and returns the
// per-column alignment, or `null` if `line` isn't one — used both to detect
// where a table starts and to read its column alignment.
function parseTableAlignRow(line: string): TableAlign[] | null {
  if (!line.includes('|')) return null;
  const cells = splitTableCells(line);
  if (!cells.every((cell) => TABLE_ALIGN_CELL.test(cell))) return null;
  return cells.map((cell) => COLUMN_ALIGN[`${cell[0]}${cell.at(-1)}` as keyof typeof COLUMN_ALIGN]);
}

// A table starts at `i` when `lines[i]` is a pipe-bearing header row
// immediately followed by a valid alignment row at `lines[i + 1]`.
function isTableStartAt(lines: string[], i: number): boolean {
  const sep = lines[i + 1];
  if (sep === undefined) return false;
  if (!lines[i]!.includes('|')) return false;
  return parseTableAlignRow(sep) !== null;
}

// Collects the body rows following a table's header + alignment row —
// every subsequent non-blank, pipe-bearing line, matching OD's greedy
// table-body rule. Called only once `isTableStartAt` has confirmed `i`
// through `i + 1` are the header/alignment pair; returns the new cursor.
function collectTableRows(lines: string[], start: number): { rows: string[][]; next: number } {
  const rows: string[][] = [];
  let i = start;
  while (i < lines.length) {
    const row = lines[i]!;
    if (row.trim() === '' || !row.includes('|')) break;
    rows.push(splitTableCells(row));
    i++;
  }
  return { rows, next: i };
}

const ORDERED_ITEM = /^\s*\d+[.)]\s+/;
const FENCE = /^```/;
const HEADING = /^(#{1,3})\s+/;
const RULE = /^(-{3,}|\*{3,}|_{3,})\s*$/;
const QUOTE_LINE = /^>\s?/;
const BULLET_ITEM = /^\s*[-*]\s+/;

// Every `lines[i]` access in the block parsers below is guarded by an
// `i < lines.length` check (either `parseBlocks`' own loop condition or an
// inner `while`'s left-hand operand, short-circuited before the index is
// read) — `lines` is a `string[]` from `String.prototype.split`, which never
// contains `undefined` entries, so the index is always in range and always a
// string. The `?? ''`/non-null-assertion sites below are TS-only fallbacks
// for `noUncheckedIndexedAccess`-style indexing with no real runtime path;
// using `!` documents that instead of instrumenting an unreachable branch
// (same convention as `ToolCard.tsx`'s `baseName` comment).
type ParsedBlock = { block: Block; next: number };
type BlockParser = (lines: string[], i: number) => ParsedBlock | null;

function parseFence(lines: string[], i: number): ParsedBlock | null {
  const line = lines[i]!;
  if (!FENCE.test(line)) return null;
  const lang = line.slice(3).trim() || null;
  const body: string[] = [];
  let j = i + 1;
  while (j < lines.length && !FENCE.test(lines[j]!)) {
    body.push(lines[j]!);
    j += 1;
  }
  // `j + 1` skips the closing fence (or end of input if unterminated).
  return { block: { kind: 'code', lang, body: body.join('\n') }, next: j + 1 };
}

function parseHeading(lines: string[], i: number): ParsedBlock | null {
  const heading = HEADING.exec(lines[i]!);
  if (!heading) return null;
  const content = /^(.*)$/.exec(lines[i]!.slice(heading[0].length));
  if (!content) return null;
  // Both captures are mandatory in their respective patterns, so each successful match has a
  // defined group 1 — same dead-fallback reasoning as the `lines[i]` accesses above.
  return { block: { kind: 'h', level: heading[1]!.length as 1 | 2 | 3, text: content[1]! }, next: i + 1 };
}

function parseRule(lines: string[], i: number): ParsedBlock | null {
  return RULE.test(lines[i]!) ? { block: { kind: 'hr' }, next: i + 1 } : null;
}

// Collects the run of consecutive lines matching `marker`, each with that
// marker stripped — the shape of blockquotes.
function collectMarked(lines: string[], start: number, marker: RegExp): { items: string[]; next: number } {
  const items: string[] = [];
  let i = start;
  while (i < lines.length && marker.test(lines[i]!)) {
    items.push(lines[i]!.replace(marker, ''));
    i += 1;
  }
  return { items, next: i };
}

function parseQuote(lines: string[], i: number): ParsedBlock | null {
  if (!QUOTE_LINE.test(lines[i]!)) return null;
  const { items, next } = collectMarked(lines, i, QUOTE_LINE);
  return { block: { kind: 'bq', text: items.join('\n') }, next };
}

// A list item runs on over the following lines until a blank line or another block starts
// (CommonMark's lazy continuation). Without it, a wrapped item such as "- **Grafana Cloud (instance
// ID +\n  token)**" split into an item and a paragraph, and both halves showed raw `**`.
function collectItem(lines: string[], i: number, marker: RegExp): { item: string; next: number } {
  let item = lines[i]!.replace(marker, '');
  let j = i + 1;
  while (j < lines.length && lines[j]!.trim() !== '' && !isBlockStart(lines, j)) {
    item += `\n${lines[j]!.trim()}`;
    j += 1;
  }
  return { item, next: j };
}

function parseBulletList(lines: string[], i: number): ParsedBlock | null {
  if (!BULLET_ITEM.test(lines[i]!)) return null;
  const items: string[] = [];
  let j = i;
  while (j < lines.length && BULLET_ITEM.test(lines[j]!)) {
    const { item, next } = collectItem(lines, j, BULLET_ITEM);
    items.push(item);
    j = next;
  }
  return { block: { kind: 'ul', items }, next: j };
}

function parseTable(lines: string[], i: number): ParsedBlock | null {
  if (!isTableStartAt(lines, i)) return null;
  const aligns = parseTableAlignRow(lines[i + 1]!)!;
  const headers = splitTableCells(lines[i]!);
  const { rows, next } = collectTableRows(lines, i + 2);
  return { block: { kind: 'table', aligns, headers, rows }, next };
}

function parseOrderedList(lines: string[], i: number): ParsedBlock | null {
  const line = lines[i]!;
  if (!ORDERED_ITEM.test(line)) return null;
  const start = Number(/\d+/.exec(line)![0]);
  const items: string[] = [];
  let j = i;
  while (j < lines.length && ORDERED_ITEM.test(lines[j]!)) {
    const { item, next } = collectItem(lines, j, ORDERED_ITEM);
    items.push(item);
    j = nextLooseListLine(lines, next);
  }
  return { block: { kind: 'ol', start, items }, next: j };
}

// Tried in this order at each non-blank line; the first match wins, and a
// line none of them claims starts a paragraph.
const BLOCK_PARSERS: readonly BlockParser[] = [
  parseFence,
  parseHeading,
  parseRule,
  parseQuote,
  parseBulletList,
  parseTable,
  parseOrderedList,
];

function parseParagraph(lines: string[], i: number): ParsedBlock {
  const paragraph: string[] = [];
  let j = i;
  while (j < lines.length && lines[j]!.trim() !== '' && !isBlockStart(lines, j)) {
    paragraph.push(lines[j]!);
    j += 1;
  }
  return { block: { kind: 'p', text: paragraph.join('\n') }, next: j };
}

function parseBlockAt(lines: string[], i: number): ParsedBlock {
  for (const parse of BLOCK_PARSERS) {
    const parsed = parse(lines, i);
    if (parsed) return parsed;
  }
  return parseParagraph(lines, i);
}

function parseBlocks(input: string): Block[] {
  const lines = input.split(/\r?\n/);
  const blocks: Block[] = [];
  let i = 0;
  while (i < lines.length) {
    if (lines[i]!.trim() === '') {
      i += 1;
      continue;
    }
    const { block, next } = parseBlockAt(lines, i);
    blocks.push(block);
    i = next;
  }
  return blocks;
}

/**
 * A "loose" numbered list puts a blank line between items ("1. a\n\n2. b").
 * Skip those blank lines when the next non-blank line is another numbered
 * item, so the items stay in ONE `<ol>` (numbered 1..n) instead of n lists
 * that each show "1.". Otherwise return `i` unchanged and the list ends.
 */
function nextLooseListLine(lines: string[], i: number): number {
  let j = i;
  while (j < lines.length && lines[j]!.trim() === '') j += 1;
  return j > i && j < lines.length && ORDERED_ITEM.test(lines[j]!) ? j : i;
}

function isBlockStart(lines: string[], i: number): boolean {
  const line = lines[i]!;
  const simpleBlock = [FENCE, /^(#{1,3})\s+/, RULE, QUOTE_LINE, BULLET_ITEM, ORDERED_ITEM].some(pattern => pattern.test(line));
  return simpleBlock || isTableStartAt(lines, i);
}

function renderBlock(block: Block): ReactNode {
  switch (block.kind) {
    case 'h': {
      const Tag = (`h${block.level}` as const) as 'h1' | 'h2' | 'h3';
      return <Tag>{renderInline(block.text)}</Tag>;
    }
    case 'p':
      return <p>{renderInline(block.text)}</p>;
    case 'ul':
      return (
        <ul>
          {block.items.map((item, i) => (
            <li key={i}>{renderInline(item)}</li>
          ))}
        </ul>
      );
    case 'ol':
      return (
        <ol start={block.start === 1 ? undefined : block.start}>
          {block.items.map((item, i) => (
            <li key={i}>{renderInline(item)}</li>
          ))}
        </ol>
      );
    case 'bq':
      return <blockquote>{renderInline(block.text)}</blockquote>;
    case 'code':
      return <CodeBlock lang={block.lang} body={block.body} />;
    case 'table':
      return <TableBlock aligns={block.aligns} headers={block.headers} rows={block.rows} />;
    case 'hr':
      return <hr />;
  }
  return undefined;
}

interface CodeBlockProps {
  lang: string | null;
  body: string;
}

// Fenced code block ('renderBlock' case 'code') plus its copy affordance. 'CopyCodeButton' below
// sits in its own small toolbar row above the '<pre>', not overlaid on top of it: an overlay
// button would sit over whatever code happens to render at that corner, and '.jini-message-
// content pre' already carries its own horizontal scrollbar at the bottom of the element -- a
// separate row above avoids colliding with either.
function CodeBlock({ lang, body }: CodeBlockProps): ReactNode {
  return (
    <div className="jini-md-code-block">
      <div className="jini-md-code-toolbar">
        <CopyCodeButton code={body} />
      </div>
      <pre>
        <code data-lang={lang ?? undefined}>{body}</code>
      </pre>
    </div>
  );
}

interface CopyCodeButtonProps {
  /** The fenced block's exact source text -- never a DOM/innerText read, so it survives the round trip byte-for-byte (indentation, trailing spaces, any markup-like characters inside the fence). */
  code: string;
}

// Per-block copy affordance for CodeBlock above. Mirrors MessageRow.tsx's CopyMessageButton
// one-for-one in shape -- same hook, same icon swap, same visually-hidden aria-live announce --
// but stays its own component rather than a shared one; see this module's header comment for why.
function CopyCodeButton({ code }: CopyCodeButtonProps): ReactNode {
  const t = useT();
  const { copied, copy } = useCopyToClipboard();
  return (
    <>
      <button
        type="button"
        className="jini-md-code-copy"
        aria-label={copied ? t('Copied') : t('Copy code')}
        onClick={() => {
          void copy(code);
        }}
      >
        <Icon name={copied ? 'check' : 'copy'} />
      </button>
      {/* Visually hidden, not decorative -- same reasoning as MessageRow.tsx's own copy-status
          span: the icon swap above says nothing to a screen reader on its own. */}
      <span className="jini-md-code-copy-status" aria-live="polite">
        {copied ? t('Copied to clipboard') : ''}
      </span>
    </>
  );
}

interface TableBlockProps {
  aligns: TableAlign[];
  headers: string[];
  rows: string[][];
}

// Renders the `<table>` element itself — shared between the inline (possibly
// scroll-clipped) copy and the pop-out modal's full-size copy, so the two
// never drift. Each cell goes through the same `renderInline` pass every
// other block uses, so `**bold**`/`` `code` ``/links inside a cell render as
// markup rather than literal text.
function renderTableElement({ aligns, headers, rows }: TableBlockProps): ReactNode {
  const cellStyle = (idx: number): { textAlign: 'left' | 'right' | 'center' } | undefined => {
    const align = aligns[idx];
    return align ? { textAlign: align } : undefined;
  };
  return (
    <table className="jini-md-table">
      <thead>
        <tr>
          {headers.map((cell, idx) => (
            <th key={idx} style={cellStyle(idx)}>{renderInline(cell)}</th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row, rowIndex) => (
          <tr key={rowIndex}>
            {headers.map((_, cellIndex) => (
              <td key={cellIndex} style={cellStyle(cellIndex)}>{renderInline(row[cellIndex] ?? '')}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

// Width-only overflow check for the table wrap below — a *deliberately*
// narrower copy of the downstream host's own overflow-detection hook (see
// this file's own module doc), same `ResizeObserver` + mount-time-check
// shape, not an import of it: this package cannot depend on a downstream
// host's app code, and a table can only ever overflow horizontally (its
// wrap never constrains height), so this version skips that hook's
// vertical-axis branch entirely.
const TABLE_OVERFLOW_SLACK_PX = 1;

function useTableOverflow(): { wrapRef: RefObject<HTMLDivElement | null>; isOverflowing: boolean } {
  const wrapRef = useRef<HTMLDivElement>(null);
  const [isOverflowing, setIsOverflowing] = useState(false);

  useEffect(() => {
    // The wrap div renders unconditionally, so its ref is attached by the time this effect runs.
    const el = wrapRef.current!;
    if (typeof ResizeObserver !== 'function') return undefined;
    const check = () => setIsOverflowing(el.scrollWidth > el.clientWidth + TABLE_OVERFLOW_SLACK_PX);
    const observer = new ResizeObserver(check);
    observer.observe(el);
    check();
    return () => observer.disconnect();
  }, []);

  return { wrapRef, isOverflowing };
}

// Wide-table pop-out: the inline table always renders (scroll-clipped by its
// own `.jini-md-table-wrap` if wider than the message column), and once it
// genuinely overflows its own box an "Expand table" button appears to reopen
// it full-size in a native `<dialog>` — same open/close/backdrop/Escape
// lifecycle as the downstream host's own overflow-modal component (see this
// file's own module doc), kept self-contained here for the same reason
// `useTableOverflow` above is: no downstream-host dependency, and every
// Jini host gets the affordance.
// `<dialog>`'s `showModal`/`close` methods are unimplemented in jsdom (and on any real browser too
// old to support the element at all) — falls back to the plain `open` attribute in either case,
// same guarded fallback shape that host component's own dialog lifecycle hook uses for the
// identical reason.
function openTableDialog(dialog: HTMLDialogElement): void {
  if (typeof dialog.showModal === 'function') {
    if (!dialog.open) dialog.showModal();
    return;
  }
  dialog.setAttribute('open', '');
}

function closeTableDialog(dialog: HTMLDialogElement): void {
  if (typeof dialog.close === 'function') {
    if (dialog.open) dialog.close();
    return;
  }
  dialog.removeAttribute('open');
}

function TableBlock(props: TableBlockProps): ReactNode {
  const { wrapRef, isOverflowing } = useTableOverflow();
  const [expanded, setExpanded] = useState(false);
  const dialogRef = useRef<HTMLDialogElement>(null);

  useEffect(() => {
    // The `<dialog>` renders unconditionally, so its ref is attached by the time this effect runs.
    const dialog = dialogRef.current!;
    if (expanded) openTableDialog(dialog);
    else closeTableDialog(dialog);
  }, [expanded]);

  return (
    <div className="jini-md-table-block">
      <div className="jini-md-table-wrap" ref={wrapRef}>
        {renderTableElement(props)}
      </div>
      {isOverflowing ? (
        <button type="button" className="jini-md-table-expand" onClick={() => setExpanded(true)}>
          Expand table
        </button>
      ) : null}
      <dialog
        ref={dialogRef}
        className="jini-md-table-modal"
        onCancel={(e) => {
          e.preventDefault();
          setExpanded(false);
        }}
        onClick={(e) => {
          if (e.target === dialogRef.current) setExpanded(false);
        }}
      >
        <button type="button" className="jini-md-table-modal-close" onClick={() => setExpanded(false)} aria-label="Close">
          ×
        </button>
        <div className="jini-md-table-modal-body">{expanded ? renderTableElement(props) : null}</div>
      </dialog>
    </div>
  );
}

// Inline pass: `code`, [label](url) links, **bold**, *italic*/_italic_, bare http(s) autolinks.
// Processes left-to-right with a single regex alternation so spans never
// nest incorrectly across kinds.
//
// `_italic_` follows CommonMark's word-boundary rule: an `_` with a letter,
// digit or `_` on its outer side never opens or closes emphasis, and an `_`
// between two word characters inside the span is content. The plain
// `_[^_]+_` this replaced matched intraword, so a tool-result name like
// `ANALYTICS_ROOT_KEY_SEED` rendered as `ANALYTICS<em>ROOT</em>KEY_SEED`.
// `*` stays permissive — CommonMark allows intraword `*` emphasis.
const UNDERSCORE_EM = String.raw`(?<![\p{L}\p{N}_])_(?![\s_])(?:[^_]|_(?=[\p{L}\p{N}]))+?(?<!\s)_(?![\p{L}\p{N}_])`;
// `[label](url)`: the URL may hold one level of balanced parentheses (`Foo_(bar)`), and the whole
// link may itself sit inside parentheses (`([edit](/admin/pages/x))`) — the outer `)` is left as text.
const MD_LINK = String.raw`\[[^\]\n]+\]\((?:[^()\s]|\([^()\s]*\))+\)`;
const MD_LINK_PARTS = /^\[([^\]\n]+)\]\((.+)\)$/u;
const INLINE_RE = new RegExp(String.raw`(\x60[^\x60]+\x60)|(${MD_LINK})|(\*\*[^*]+\*\*)|(\*[^*]+\*|${UNDERSCORE_EM})|(https?:\/\/[^\s)]+)`, 'gu');

// Only these targets become anchors; anything else (`javascript:`, `data:`, protocol-relative
// `//host`) stays literal text, since the text is untrusted model output.
export const SAFE_LINK_HREF = /^(?:https?:\/\/|mailto:|\/(?!\/)|#)/iu;
// Every link opens in a new tab — an in-app path too, so following one never navigates the tab the
// chat lives in (owner 2026-10-08). Only a `#` same-document anchor stays in place. ChatPane's
// click guard (`useChatPaneNewTabLinks`) covers links this renderer does not draw.
const NEW_TAB = { target: '_blank', rel: 'noopener noreferrer' } as const;

function renderMarkdownLink(source: string, key: number): ReactNode {
  // `MD_LINK` already matched `source`, so these two groups always capture.
  const [, label, href] = MD_LINK_PARTS.exec(source)!;
  if (!SAFE_LINK_HREF.test(href!)) return source;
  return (
    <a key={key} href={href} {...(href!.startsWith('#') ? {} : NEW_TAB)}>
      {renderInline(label!)}
    </a>
  );
}

function renderInline(text: string): ReactNode {
  const nodes: ReactNode[] = [];
  let lastIndex = 0;
  let key = 0;
  // A fresh copy per call, not the shared `g` regex: a link label recurses into this function
  // mid-loop, and a shared `lastIndex` would be reset under the outer scan.
  const inlineRe = new RegExp(INLINE_RE);
  let match: RegExpExecArray | null = inlineRe.exec(text);
  while (match !== null) {
    if (match.index > lastIndex) nodes.push(text.slice(lastIndex, match.index));
    const whole = match[0];
    nodes.push(renderInlineToken({ match, key }));
    key += 1;
    // `whole` is `match[0]` — a successful `RegExpExecArray` always has a
    // defined (if possibly empty) full-match string at index 0, so this
    // fallback is unreachable (same dead-fallback reasoning as above).
    lastIndex = match.index + whole!.length;
    match = inlineRe.exec(text);
  }
  if (lastIndex < text.length) nodes.push(text.slice(lastIndex));
  return nodes;
}

function renderInlineToken({ match, key }: { match: RegExpExecArray; key: number }): ReactNode {
  const [, code, mdLink, bold, italic, link] = match;
  if (code) return <code key={key}>{code.slice(1, -1)}</code>;
  if (mdLink) return renderMarkdownLink(mdLink, key);
  if (bold) return <strong key={key}>{renderInline(bold.slice(2, -2))}</strong>;
  if (italic) return <em key={key}>{renderInline(italic.slice(1, -1))}</em>;
  if (link) return <a key={key} href={link} {...NEW_TAB}>{link}</a>;
  return null;
}

type AnswerValue = string | string[] | undefined;

import { CREDENTIAL_CARD_GUIDANCE, SECRET_REDACTED_NOTICE, type UserTextRedactionOptions } from '../../core/user-text-redaction.js';
import { useUserTextGuard } from '../hooks/useUserTextGuard.js';
/**
 * @module QuestionForm
 *
 * Renders one parsed `<question-form>` as an interactive (or locked/
 * answered) set of controls. Ported from OD's `components/QuestionForm.tsx`
 * (verified 0 OD product references — the file only imports React,
 * `useT()`, and its own question-form types) against `@jini-ai/chat/core`'s
 * `QuestionForm`/`FormQuestion`/`FormOption`/`DirectionCard`/
 * `formatFormAnswers` (the same shapes, lifted verbatim into chat-core
 * already). className/structure kept verbatim (`question-form`/`qf-*`
 * classes — unstyled semantic markup, host supplies CSS); every user-facing
 * string wrapped in `useT()`.
 */
import { forwardRef, useEffect, useImperativeHandle, useMemo, useState, type ChangeEvent, type CSSProperties, type ReactNode } from 'react';
import type { DirectionCard, FormOption, QuestionForm as QuestionFormType } from '../../core/index.js';
import { formatFormAnswers, formOptionValueForLabel, redactQuestionAnswers, isSecretQuestion, withoutSecretQuestionDefaults, questionTextInputProps, questionTextareaProps } from '../../core/index.js';
import { useT } from '../hooks/context.js';
import { SecretInput, SecretTextarea } from '@jini-ai/ui';

export interface QuestionFormFileSubmission {
  questionId: string;
  questionLabel: string;
  files: File[];
}

export interface QuestionFormHandle {
  submit: () => void;
  /** Submit with no answers — every question is optional, so this records each as "(skipped)" and moves on. */
  skipAll: () => void;
}

export interface QuestionFormProps extends UserTextRedactionOptions {
  form: QuestionFormType;
  /** Whether the user can still submit answers — the host disables this once the turn is no longer the most recent one. */
  interactive: boolean;
  submittedAnswers?: Record<string, string | string[]>;
  /** When a host's own Continue button owns the submit, hide this form's footer button and report ready-state via `onReadyChange`. */
  hideInternalSubmit?: boolean;
  draftAnswers?: Record<string, string | string[]>;
  onReadyChange?: (ready: boolean) => void;
  onDraftChange?: (answers: Record<string, string | string[]>) => void;
  onAnswerChange?: (questionId: string, value: string | string[]) => void;
  onSubmit?: (text: string, answers: Record<string, string | string[]>, files?: QuestionFormFileSubmission[]) => void;
}

export const QuestionForm = forwardRef<QuestionFormHandle, QuestionFormProps>(function QuestionForm(
  { form: incomingForm, interactive, submittedAnswers, hideInternalSubmit = false, draftAnswers, onReadyChange, onDraftChange, onAnswerChange, onSubmit, redactUserText, onSecretRedacted },
  ref,
) {
  const t = useT();
  const form = useMemo(() => withoutSecretQuestionDefaults({ form: incomingForm }), [incomingForm]);
  const guard = useUserTextGuard({ ...(redactUserText ? { redactUserText } : {}), ...(onSecretRedacted ? { onSecretRedacted } : {}) });
  const locked = !interactive || !onSubmit || submittedAnswers !== undefined;
  const state = useQuestionAnswers({ form, submittedAnswers, draftAnswers, locked }, { onDraftChange, onAnswerChange });
  const currentAnswers = submittedAnswers ? redactQuestionAnswers({ form, answers: submittedAnswers }).answers : state.answers;
  const ready = answersReady(form, currentAnswers);

  function handleSubmit() {
    if (locked || !onSubmit) return;
    if (!ready) return;
    const safe = redactQuestionAnswers({ form, answers: state.answers }, { ...(redactUserText ? { redactUserText } : {}), onSecretRedacted: guard.notifyRedaction });
    state.setAnswers(safe.answers);
    const files = collectFileSubmissions(form, state.fileAnswers);
    if (files.length > 0) onSubmit(formatFormAnswers({ form: form, answers: safe.answers }), safe.answers, files);
    else onSubmit(formatFormAnswers({ form: form, answers: safe.answers }), safe.answers);
  }

  function handleSkipAll() {
    if (locked || !onSubmit) return;
    const empty: Record<string, string | string[]> = {};
    onSubmit(formatFormAnswers({ form: form, answers: empty }), empty);
  }

  useImperativeHandle(ref, () => ({ submit: handleSubmit, skipAll: handleSkipAll }));
  useEffect(() => {
    onReadyChange?.(!locked && ready);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [onReadyChange, locked, ready]);

  return (
    <div className={`question-form${locked ? ' question-form-locked' : ''}`} data-form-id={form.id}>
      <QuestionFormHead form={form} locked={locked} />
      <div className="question-form-body">
        {form.questions.map((q) => (
          <QuestionField key={q.id} q={q} value={currentAnswers[q.id]} formId={form.id} locked={locked} t={t} {...state.handlers} />
        ))}
      </div>
      {guard.secretRedacted ? <div role="status">{t(SECRET_REDACTED_NOTICE)}</div> : null}
      {hideInternalSubmit ? null : <QuestionFormFoot locked={locked} answered={submittedAnswers !== undefined} ready={ready} submitLabel={form.submitLabel} onSubmit={handleSubmit} />}
    </div>
  );
});

type Question = QuestionFormType['questions'][number];
type Answers = Record<string, string | string[]>;

/** Owns the editable answers plus the picked files; every edit is a no-op once the form is locked. */
function useQuestionAnswers(
  { form, submittedAnswers, draftAnswers, locked }: { form: QuestionFormType; submittedAnswers: Answers | undefined; draftAnswers: Answers | undefined; locked: boolean },
  { onDraftChange, onAnswerChange }: { onDraftChange?: QuestionFormProps['onDraftChange'] | undefined; onAnswerChange?: QuestionFormProps['onAnswerChange'] | undefined } = {},
) {
  const initial = useMemo(() => buildInitialState(form, submittedAnswers, draftAnswers), [form, submittedAnswers, draftAnswers]);
  const [answers, setAnswers] = useState<Answers>(initial);
  const [fileAnswers, setFileAnswers] = useState<Record<string, File[]>>({});

  useEffect(() => {
    setFileAnswers({});
  }, [form.id]);

  useEffect(() => {
    setAnswers((prev) => backfillAnswers(prev, form, submittedAnswers));
  }, [form, submittedAnswers]);

  function update(id: string, value: string | string[]) {
    if (locked) return;
    const next = { ...answers, [id]: value };
    setAnswers(next);
    onDraftChange?.(redactQuestionAnswers({ form, answers: draftSafeAnswers(form, next) }).answers);
    onAnswerChange?.(id, redactQuestionAnswers({ form, answers: { [id]: value } }).answers[id]!);
  }

  function toggleCheckbox(id: string, option: string, maxSelections?: number) {
    if (locked) return;
    const current = Array.isArray(answers[id]) ? (answers[id] as string[]) : [];
    const has = current.includes(option);
    if (!has && maxSelections !== undefined && current.length >= maxSelections) return;
    const next = has ? current.filter((v) => v !== option) : [...current, option];
    const nextAnswers = { ...answers, [id]: next };
    setAnswers(nextAnswers);
    onDraftChange?.(redactQuestionAnswers({ form, answers: draftSafeAnswers(form, nextAnswers) }).answers);
    onAnswerChange?.(id, next);
  }

  function updateCheckboxCustom(q: Question, raw: string) {
    if (locked) return;
    const current = Array.isArray(answers[q.id]) ? (answers[q.id] as string[]) : [];
    const fixed = current.filter((entry) => questionValueIsKnown(q, entry));
    update(q.id, [...fixed, ...splitCustomEntries(raw)]);
  }

  function selectFiles(q: Question, list: FileList | null) {
    const files = Array.from(list ?? []);
    const names = files.map((file) => file.name);
    setFileAnswers((current) => ({ ...current, [q.id]: files }));
    update(q.id, q.multiple ? names : (names[0] ?? ''));
  }

  return { answers, setAnswers, fileAnswers, handlers: { update, toggleCheckbox, updateCheckboxCustom, selectFiles } };
}

function answersReady(form: QuestionFormType, answers: Answers): boolean {
  const withinSelectionLimits = form.questions.every((q) => {
    if (q.type !== 'checkbox' || q.maxSelections === undefined) return true;
    const v = answers[q.id];
    return !Array.isArray(v) || v.length <= q.maxSelections;
  });
  const requiredAnswered = form.questions.every((q) => {
    if (q.required !== true) return true;
    const v = answers[q.id];
    if (Array.isArray(v)) return v.length > 0;
    return typeof v === 'string' && v.trim().length > 0;
  });
  return withinSelectionLimits && requiredAnswered;
}

function QuestionFormHead({ form, locked }: { form: QuestionFormType; locked: boolean }) {
  const t = useT();
  return (
    <div className="question-form-head">
      <span className="question-form-icon" aria-hidden>
        ?
      </span>
      <div className="question-form-titles">
        <div className="question-form-title">{form.title}</div>
        {form.description ? <div className="question-form-desc">{form.description}</div> : null}
      </div>
      {locked ? <span className="question-form-pill">{t('Answered')}</span> : null}
    </div>
  );
}

function QuestionFormFoot({ locked, answered, ready, submitLabel, onSubmit }: { locked: boolean; answered: boolean; ready: boolean; submitLabel: string | undefined; onSubmit: () => void }) {
  const t = useT();
  return (
    <div className="question-form-foot">
      {locked ? <span className="qf-locked-note">{answered ? t('You answered this') : t('A newer message answered this')}</span> : <span className="qf-hint">{t('Answer above, then continue')}</span>}
      {!locked ? (
        <button type="button" className="primary" onClick={onSubmit} disabled={!ready} title={ready ? t('Submit your answers') : t('Answer the required questions first')}>
          {submitLabel ?? t('Continue')}
        </button>
      ) : null}
    </div>
  );
}

/** Everything one question's control needs: its value plus the form-level edit handlers. */
type FieldHandlers = ReturnType<typeof useQuestionAnswers>['handlers'];
interface FieldContext extends FieldHandlers {
  q: Question;
  value: AnswerValue;
  formId: string;
  locked: boolean;
  t: ReturnType<typeof useT>;
}

function QuestionField(ctx: FieldContext) {
  const { q, t } = ctx;
  const renderControl = QUESTION_CONTROLS[q.type];
  return (
    <div className="qf-field">
      <label className="qf-label">
        <span>{q.label}</span>
        {q.required ? (
          <span className="qf-required" aria-label={t('required')}>
            *
          </span>
        ) : null}
      </label>
      {q.help ? <div className="qf-help">{q.help}</div> : null}
      {isSecretQuestion({ question: q }) ? <div className="qf-help">{t(CREDENTIAL_CARD_GUIDANCE)}</div> : null}
      {renderControl ? renderControl(ctx) : null}
    </div>
  );
}

function stringValue(value: AnswerValue): string {
  return typeof value === 'string' ? value : '';
}

/** A range with no usable answer yet (e.g. mid-stream) shows its minimum, matching `emptyQuestionValue`. */
function rangeValue(q: Question, value: AnswerValue): string {
  return typeof value === 'string' && value.trim() ? value : String(q.min ?? 0);
}

function customChoice({ q, t, locked }: FieldContext, value: string, onChange: (next: string) => void) {
  if (!shouldRenderCustomChoice(q)) return null;
  return <CustomChoiceInput label={q.customLabel ?? t('Something else')} value={value} placeholder={q.customPlaceholder ?? t('Type your own answer')} disabled={locked} onChange={onChange} />;
}

function singleCustomChoice(ctx: FieldContext) {
  return customChoice(ctx, customSingleValue(ctx.q, ctx.value), (next) => ctx.update(ctx.q.id, next));
}

function RadioControl(ctx: FieldContext) {
  const { q, value, formId, locked, update } = ctx;
  if (!q.options) return null;
  return (
    <>
      <div className="qf-options">
        {q.options.map((opt) => (
          <label key={opt.value} className={`qf-chip${value === opt.value ? ' qf-chip-on' : ''}`} title={opt.description}>
            <input type="radio" name={`${formId}-${q.id}`} value={opt.value} checked={value === opt.value} disabled={locked} aria-label={opt.label} onChange={() => update(q.id, opt.value)} />
            <OptionCopy option={opt} />
          </label>
        ))}
      </div>
      {singleCustomChoice(ctx)}
    </>
  );
}

function CheckboxControl(ctx: FieldContext) {
  const { q, value, locked, toggleCheckbox, updateCheckboxCustom } = ctx;
  if (!q.options) return null;
  const arr = Array.isArray(value) ? value : [];
  return (
    <>
      <div className="qf-options">
        {q.options.map((opt) => {
          const on = arr.includes(opt.value);
          const maxed = q.maxSelections !== undefined && !on && arr.length >= q.maxSelections;
          return (
            <label key={opt.value} title={opt.description} className={`qf-chip${on ? ' qf-chip-on' : ''}${maxed ? ' qf-chip-disabled' : ''}`}>
              <input type="checkbox" value={opt.value} checked={on} disabled={locked || maxed} aria-label={opt.label} onChange={() => toggleCheckbox(q.id, opt.value, q.maxSelections)} />
              <OptionCopy option={opt} />
            </label>
          );
        })}
      </div>
      {customChoice(ctx, customCheckboxValue(q, value), (next) => updateCheckboxCustom(q, next))}
    </>
  );
}

function SelectControl(ctx: FieldContext) {
  const { q, value, locked, t, update } = ctx;
  if (!q.options) return null;
  return (
    <>
      <select className="qf-select" value={typeof value === 'string' && questionValueIsKnown(q, value) ? value : ''} disabled={locked} onChange={(e) => update(q.id, e.target.value)}>
        <option value="" disabled>
          {q.placeholder ?? t('Choose one')}
        </option>
        {q.options.map((opt) => (
          <option key={opt.value} value={opt.value} title={opt.description}>
            {opt.label}
          </option>
        ))}
      </select>
      {singleCustomChoice(ctx)}
    </>
  );
}

function DirectionCardsControl(ctx: FieldContext) {
  const { q, value, formId, locked, update } = ctx;
  if (!q.cards || q.cards.length === 0) return null;
  return (
    <>
      <div className="qf-direction-cards">
        {q.cards.map((card) => (
          <DirectionCardView key={card.id} card={card} formId={formId} questionId={q.id} selected={value === card.id || value === card.label} disabled={locked} onSelect={() => update(q.id, card.id)} />
        ))}
      </div>
      {singleCustomChoice(ctx)}
    </>
  );
}

/** A credential-shaped text question gets the shared eye toggle (hidden by default). */
function TextControl({ q, value, locked, update, t }: FieldContext) {
  const shared = { className: 'qf-input', value: stringValue(value), placeholder: q.placeholder, disabled: locked, onChange: (e: ChangeEvent<HTMLInputElement>) => update(q.id, e.target.value) };
  const props = questionTextInputProps({ question: q });
  const { type, ...secretProps } = props;
  if (type === 'password') {
    return <SecretInput {...secretProps} {...shared} aria-label={q.label} label={q.label} toggleLabels={{ show: `${t('Show')} ${q.label}`, hide: `${t('Hide')} ${q.label}` }} />;
  }
  return <input {...props} {...shared} />;
}

/** A credential-shaped textarea gets the same eye toggle; `SecretTextarea` owns the masking style. */
function TextareaControl({ q, value, locked, update, t }: FieldContext) {
  const shared = { className: 'qf-textarea', value: stringValue(value), placeholder: q.placeholder, disabled: locked, rows: 3, onChange: (e: ChangeEvent<HTMLTextAreaElement>) => update(q.id, e.target.value) };
  const props = questionTextareaProps({ question: q });
  if (isSecretQuestion({ question: q })) {
    return <SecretTextarea {...props} {...shared} aria-label={q.label} label={q.label} toggleLabels={{ show: `${t('Show')} ${q.label}`, hide: `${t('Hide')} ${q.label}` }} />;
  }
  return <textarea {...props} {...shared} />;
}

/** date/time/datetime-local and url/email/tel share one plain input whose `type` is the question type. */
function TypedInputControl({ q, value, locked, update }: FieldContext) {
  return <input type={q.type} className="qf-input" value={stringValue(value)} placeholder={q.placeholder} disabled={locked} onChange={(e) => update(q.id, e.target.value)} />;
}

const QUESTION_CONTROLS: Record<Question['type'], (ctx: FieldContext) => ReactNode> = {
  radio: RadioControl,
  checkbox: CheckboxControl,
  select: SelectControl,
  'direction-cards': DirectionCardsControl,
  text: TextControl,
  number: ({ q, value, locked, update }) => <input type="number" className="qf-input" value={stringValue(value)} placeholder={q.placeholder} min={q.min} max={q.max} step={q.step} disabled={locked} onChange={(e) => update(q.id, e.target.value)} />,
  range: ({ q, value, locked, update }) => (
    <div className="qf-range-wrap">
      <input type="range" className="qf-range" value={rangeValue(q, value)} min={q.min} max={q.max} step={q.step} disabled={locked} onChange={(e) => update(q.id, e.target.value)} />
      <output className="qf-range-value">{rangeValue(q, value)}</output>
    </div>
  ),
  date: TypedInputControl,
  time: TypedInputControl,
  'datetime-local': TypedInputControl,
  url: TypedInputControl,
  email: TypedInputControl,
