    >
      {/* The provider's own mark in API mode — the selected CLI's logo would be an outright false
          claim about what answers the next message. `AgentIcon` resolves the brand asset the host
          ships (e.g. `gemini.svg`); the generic link glyph is the fallback for a provider the host
          has no mark for, which is honest rather than wrong. */}
      <RuntimeTriggerIcon picker={picker} isApi={isApi} byokRuntime={byokRuntime} agentIconBasePath={agentIconBasePath} />
      {/* The agent name stays in the text (visually hidden; the icon already names it) so the
          trigger still reads "Choose agent" when none is picked; "agent · model" is the hover
          title above. In local mode the model is its own drop-up beside this button, so only
          API mode shows the model here — its picker still lives in the popover. */}
      <span className="jini-runtime-trigger__copy">
        <strong>{picker.triggerTitle}</strong>
        {isApi ? <small>{picker.modelLabel}</small> : null}
      </span>
      {isApi ? (
        <RemixIcon
          name="arrow-down-s-line"
          size={15}
          className="jini-runtime-trigger__chevron"
        />
      ) : null}
    </button>
  );
}

interface RuntimePopoverProps {
  base: string | undefined;
  picker: UseAgentRuntimePickerResult;
  value: ChatPaneAgentSelection;
  onChange: (selection: ChatPaneAgentSelection) => void;
  onRescan: (() => void) | undefined;
  scanning: boolean;
  daemonOnline: boolean;
  executionMode: 'local' | 'api';
  apiModeAvailable: boolean;
  onExecutionModeChange: ((mode: 'local' | 'api') => void) | undefined;
  byokRuntime: ByokRuntimeSummary | undefined;
  onByokModelChange: ((model: string) => void) | undefined;
  agentIconBasePath: string | undefined;
  t: (key: string) => string;
}

/** Keep native-dialog ownership and the originating page across a host overlay portal. */
function runtimePortalBinding({ trigger, overlay }: { trigger: HTMLElement | null; overlay: HTMLElement | null }) {
  return {
    container: trigger?.closest('dialog') ?? overlay,
    page: trigger?.closest('[data-agent-page]')?.getAttribute('data-agent-page') ?? undefined,
  };
}

function RuntimePopover({
  base,
  picker,
  value,
  onChange,
  onRescan,
  scanning,
  daemonOnline,
  executionMode,
  apiModeAvailable,
  onExecutionModeChange,
  byokRuntime,
  onByokModelChange,
  agentIconBasePath,
  t,
}: RuntimePopoverProps): ReactNode {
  const overlay = useOverlayContainer({});
  const portal = runtimePortalBinding({ trigger: picker.triggerRef.current, overlay });
  if (!picker.open || !picker.position || !portal.container) return null;
  const isApi = executionMode === 'api';
  return createPortal(
    <div
      ref={picker.popoverRef}
      className="jini-runtime-popover"
      data-agent-page={portal.page}
      // Carries the host's theme across the portal — see `originTheme`'s own comment for the
      // dark-on-dark select this exists to prevent.
      {...(picker.originTheme ? { 'data-theme': picker.originTheme } : {})}
      id={picker.dialogId}
      role="dialog"
      aria-label={t('Choose AI runtime')}
      aria-modal="false"
      style={picker.position}
      onKeyDown={picker.handlePopoverKeyDown}
    >
      <div className="jini-runtime-popover__head">
        <strong>{executionMode === 'local' ? t('Local CLI') : t('API · BYOK')}</strong>
        <span>{picker.runtimeSummary}</span>
      </div>
      <RuntimeModeButtons
        base={base}
        executionMode={executionMode}
        daemonOnline={daemonOnline}
        apiModeAvailable={apiModeAvailable}
        onExecutionModeChange={onExecutionModeChange}
        t={t}
      />

      {isApi ? (
        <RuntimeByokDetails base={base} byokRuntime={byokRuntime} onByokModelChange={onByokModelChange} t={t} />
      ) : (
        <>
          <div className="jini-runtime-section-label">{t('Code agent')}</div>
          <div role="radiogroup" aria-label={t('Code agent')}>
            <RuntimeAgentList
              base={base}
              orderedAgents={picker.orderedAgents}
              value={value}
              onChange={onChange}
              {...definedProps({ source: { agentIconBasePath } })}
              t={t}
            />
          </div>

          <RuntimeRescanFooter base={base} onRescan={onRescan} scanning={scanning} t={t} />
        </>
      )}
    </div>,
    portal.container,
  );
}

/**
 * Renders the package-owned local/API, agent, model, and reasoning picker.
 *
 * @complexity Time: O(n) in the runtime inventory; space: O(n) for ordering.
 * @overallScore 100/100
 */
export function AgentRuntimePicker({
  agentHandle,
  agents,
  nativeToolPolicy,
  value,
  onChange,
  onRescan,
  scanning = false,
  daemonOnline = true,
  placement = 'up',
  executionMode = 'local',
  apiModeAvailable = false,
  onExecutionModeChange,
  byokRuntime,
  onByokModelChange,
  // No default here (was '/agent-icons'): omitted means "let AgentIcon fall back to its own
  // bundled icon set" — see AgentIcon.tsx's BUNDLED_ICON_URLS. A host that still wants to vendor
  // its own asset directory can pass this explicitly, same as before.
  agentIconBasePath,
}: AgentRuntimePickerProps) {
  const base = useAgentHandle({ agentHandle });
  const t = useT();
  const picker = useAgentRuntimePicker({ agents, value, placement, t, executionMode, byokRuntime });

  // The one branch this component makes. Everything below the mode buttons describes a detected CLI
  // — the agent radios, its model and reasoning selects, and the PATH rescan — and none of it is
  // true of, or has any effect on, an API turn. Previously all of it rendered in both modes, so an
  // operator on BYOK saw a CLI named as "selected" and a model reading "Default (CLI config)"
  // while their messages went to a provider over an API key.
  const isApi = executionMode === 'api';

  return (
    <div className="jini-runtime-picker">
      <RuntimeTrigger base={base} picker={picker} isApi={isApi} byokRuntime={byokRuntime} agentIconBasePath={agentIconBasePath} t={t} />
      {isApi ? null : (
        <RuntimeBarMenus base={base} selectedAgent={picker.selectedAgent} value={value} onChange={onChange} modelLabel={picker.modelLabel} t={t} />
      )}
      <NativeToolPolicyWarning agent={picker.selectedAgent} policy={nativeToolPolicy} isApi={isApi} />

      <RuntimePopover
        base={base}
        picker={picker}
        value={value}
        onChange={onChange}
        onRescan={onRescan}
        scanning={scanning}
        daemonOnline={daemonOnline}
        executionMode={executionMode}
        apiModeAvailable={apiModeAvailable}
        onExecutionModeChange={onExecutionModeChange}
        byokRuntime={byokRuntime}
        onByokModelChange={onByokModelChange}
        agentIconBasePath={agentIconBasePath}
        t={t}
      />
    </div>
  );
}

import type { ReactNode } from 'react';
import { createPortal } from 'react-dom';
import { RemixIcon, infoTipBubbleStyle, useInfoTip, useAgentHandle } from '@jini-ai/ui';

import { agentHandleProps, agentHandleSegment } from '@jini-ai/agentic';
import { useRuntimeDropUp, type UseRuntimeDropUpResult } from '../hooks/useRuntimeDropUp.hooks.js';

export interface RuntimeDropUpProps {
  agentHandle?: string | false | undefined;
  /** Names both the trigger (with the current value appended) and the menu. */
  label: string;
  /** What the trigger shows: the current choice's display label. */
  valueLabel: string;
  /** A shorter form the trigger shows instead (e.g. "Opus 5.5"); the full `valueLabel` then
   *  appears in a hover/focus tooltip and stays the trigger's accessible name. */
  triggerLabel?: string | undefined;
  value: string;
  options: readonly { id: string; label: string }[];
  onSelect: (id: string) => void;
  /** Small muted line above the options (e.g. the model catalog's "Cached · …" note). */
  note?: string | undefined;
  /** Menu width cap in px; the menu is also clamped to the viewport. */
  width: number;
  className?: string;
}

type RuntimeDropUpTip = ReturnType<typeof useInfoTip>;

/** The full `valueLabel` in the same white bubble `InfoTip` uses, portalled to `document.body`. */
function RuntimeDropUpTipBubble({ tip, valueLabel }: { tip: RuntimeDropUpTip; valueLabel: string }): ReactNode {
  return createPortal(
    <span
      ref={tip.bubbleRef}
      className={tip.placement === 'below' ? 'info-tip-bubble info-tip-bubble-below' : 'info-tip-bubble'}
      role="presentation"
      aria-hidden="true"
      style={infoTipBubbleStyle(tip.coords)}
    >
      {valueLabel}
    </span>,
    document.body,
  );
}

interface RuntimeDropUpMenuProps {
  base: string | undefined;
  dropUp: UseRuntimeDropUpResult;
  label: string;
  value: string;
  options: RuntimeDropUpProps['options'];
  onSelect: (id: string) => void;
  note: string | undefined;
}

function RuntimeDropUpMenu({ base, dropUp, label, value, options, onSelect, note }: RuntimeDropUpMenuProps): ReactNode {
  if (!dropUp.open || !dropUp.position) return null;
  return (
    <div
      ref={dropUp.menuRef}
      id={dropUp.menuId}
      role="menu"
      aria-label={label}
      className="jini-runtime-dropup"
      style={dropUp.position}
      onKeyDown={dropUp.handleMenuKeyDown}
    >
      {note ? <div className="jini-runtime-dropup__note">{note}</div> : null}
      {options.map((option) => {
        const active = option.id === value;
        return (
          <button
            type="button"
            {...agentHandleProps({}, { base, action: `option-${agentHandleSegment({ value: option.id })}`, role: 'button', label: option.label })}
            role="menuitemradio"
            aria-checked={active}
            className={`jini-runtime-dropup__item${active ? ' is-active' : ''}`}
            key={option.id}
            onClick={() => dropUp.choose(() => onSelect(option.id))}
          >
            <span className="jini-runtime-dropup__item-label">{option.label}</span>
            {active ? <RemixIcon name="check-line" size={16} className="jini-runtime-check" /> : null}
          </button>
        );
      })}
    </div>
  );
}

/**
 * A compact, borderless "Label ⌄" trigger in the composer bar that opens a menu of choices above
 * itself. Used for the model and the reasoning effort; the selection itself stays with the caller.
 *
 * @complexity Time/space: O(n) in the option count.
 */
export function RuntimeDropUp({
  agentHandle,
  label,
  valueLabel,
  triggerLabel,
  value,
  options,
  onSelect,
  note,
  width,
  className,
}: RuntimeDropUpProps): ReactNode {
  const base = useAgentHandle({ agentHandle });
  const dropUp = useRuntimeDropUp({ width });
  const { menuId, open, triggerRef, toggleOpen, handleTriggerKeyDown } = dropUp;
  // The same white bubble as `InfoTip` (its hook places it), rather than the browser's own title
  // tooltip; only when the trigger shows a shortened label, so there is something to reveal.
  const tip = useInfoTip({}, { placement: 'top' });
  const shortened = triggerLabel !== undefined && triggerLabel !== valueLabel;
  // No tip over the open menu, which already lists the full name.
  const tipVisible = shortened && !open;
  const showTip = () => {
    if (tipVisible) tip.show();
  };

  return (
    <>
      <button
        {...agentHandleProps({}, { base, role: 'button', label })}
        ref={triggerRef}
        type="button"
        className={'jini-runtime-dropup-trigger' + (className ? ' ' + className : '')}
        aria-label={`${label}: ${valueLabel}`}
        aria-haspopup="menu"
        aria-expanded={open}
        aria-controls={menuId}
        {...(shortened ? {} : { title: valueLabel })}
        onClick={() => {
          tip.hide();
          toggleOpen();
        }}
        onKeyDown={(event) => {
          if (event.key === 'Escape') tip.hide();
          handleTriggerKeyDown(event);
        }}
        onMouseEnter={showTip}
        onMouseLeave={tip.leave}
        onFocus={showTip}
        onBlur={tip.hide}
      >
        <span ref={tip.iconRef} className="jini-runtime-dropup-trigger__label">{triggerLabel ?? valueLabel}</span>
        <RemixIcon name="arrow-down-s-line" size={15} className="jini-runtime-trigger__chevron" />
      </button>
      {tip.open && tipVisible ? <RuntimeDropUpTipBubble tip={tip} valueLabel={valueLabel} /> : null}
      <RuntimeDropUpMenu base={base} dropUp={dropUp} label={label} value={value} options={options} onSelect={onSelect} note={note} />
    </>
  );
}
